const supabase = {
    _session: null,
    _h: (token) => ({
        "Content-Type": "application/json",
        apikey: SUPABASE_ANON_KEY,
        Authorization: `Bearer ${token || SUPABASE_ANON_KEY}`
    }),

    async getValidToken() {
        const s = this._session;
        if (!s) return null;
        // If token expires in less than 60 seconds, refresh it
        if (s.expires_at && Date.now() / 1000 > s.expires_at - 60) {
            const refreshed = await this.auth.refreshSession(s.refresh_token);
            if (refreshed?.access_token) {
                this._session = refreshed;
                return refreshed.access_token;
            }
        }
        return s.access_token;
    },
    auth: {
        async signUp(email, password) {
            const r = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
                method: "POST",
                headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
                body: JSON.stringify({
                    email,
                    password,
                    options: {
                        emailRedirectTo: PUBLIC_SITE_URL
                    }
                })
            });
            const data = await r.json();
            if (data.error) throw new Error(data.error.message || data.msg || "Signup failed");
            return data;
        },
        async signIn(email, password) {
            const r = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
                method: "POST",
                headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
                body: JSON.stringify({ email, password })
            });
            const data = await r.json();
            if (data.access_token) {
                supabase._session = {
                    access_token: data.access_token,
                    refresh_token: data.refresh_token,
                    expires_at: Math.floor(Date.now() / 1000) + (data.expires_in || 3600),
                    user: data.user,
                };
                savePersistedSession(supabase._session);
            }
            return data;
        },
        async refreshSession(refresh_token) {
            const r = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
                method: "POST",
                headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY },
                body: JSON.stringify({ refresh_token }),
            });
            const data = await r.json();
            if (data.access_token) {
                return {
                    access_token: data.access_token,
                    refresh_token: data.refresh_token || refresh_token,
                    expires_at: Math.floor(Date.now() / 1000) + (data.expires_in || 3600),
                };
            }
            return null;
        },
        signInWithGoogle() {
            window.location.href = `${SUPABASE_URL}/auth/v1/authorize?provider=google&redirect_to=${encodeURIComponent(PUBLIC_SITE_URL)}`;
        },
        async getSessionFromHash() {
            const hash = window.location.hash;
            const search = window.location.search;
            const p = new URLSearchParams(hash.replace("#", ""));
            const q = new URLSearchParams(search.replace("?", ""));
            const access_token = p.get("access_token") || q.get("access_token");
            if (!access_token) return null;
            const r = await fetch(`${SUPABASE_URL}/auth/v1/user`, { headers: { "Content-Type": "application/json", apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${access_token}` } });
            const user = await r.json();
            window.history.replaceState(null, "", window.location.pathname);
            return { access_token, user };
        },
    },
    async db(table, token) {
        const h = this._h(token);
        return {
            select: async () => { const r = await fetch(`${SUPABASE_URL}/rest/v1/${table}?select=*&order=entry_date.desc`, { headers: h }); return r.json(); },
            insert: async (data) => { const r = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, { method: "POST", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify(data) }); return r.json(); },
            update: async (id, data) => { const r = await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${id}`, { method: "PATCH", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify(data) }); return r.json(); },
            delete: async (id) => { await fetch(`${SUPABASE_URL}/rest/v1/${table}?id=eq.${id}`, { method: "DELETE", headers: h }); },
        };
    },
};

