function calcTrade(t) {
    const buyAmt = t.buy_qty * t.buy_price;
    const sellAmt = (t.sell_qty || 0) * (t.sell_price || 0);
    const pnl = t.exit_date ? sellAmt - buyAmt : null;
    const days = t.exit_date ? Math.round((new Date(t.exit_date) - new Date(t.entry_date)) / 86400000) : null;
    return { ...t, buyAmt, sellAmt, pnl, days };
}
function buildTradeRows(trades) {
    return trades.map(calcTrade);
}
function calcStatsFromRows(tradeRows) {
    // PREPARE CLOSED TRADES
    const closed = tradeRows.filter(t => t.exit_date);

    const wins = closed.filter(t => t.pnl > 0);
    const losses = closed.filter(t => t.pnl <= 0);

    // -----------------------------------------
    //  EXCEL-STYLE WEIGHTED AVG GAIN & LOSS %


    const totalGainPnl = wins.reduce((s, t) => s + t.pnl, 0);
    const totalGainBuy = wins.reduce((s, t) => s + t.buyAmt, 0);
    const avgGain = totalGainBuy !== 0 ? (totalGainPnl / totalGainBuy) * 100 : 0;

    const totalLossPnl = losses.reduce((s, t) => s + t.pnl, 0);
    const totalLossBuy = losses.reduce((s, t) => s + t.buyAmt, 0);
    const avgLoss = totalLossBuy !== 0 ? (totalLossPnl / totalLossBuy) * 100 : 0;

    // --------------------------------------------------------
    //  EXCEL-STYLE WEIGHTED AVG HOLDING DAYS

    const totalHoldWin = wins.reduce((s, t) => s + (t.days * t.buyAmt), 0);
    const totalBuyWin = wins.reduce((s, t) => s + t.buyAmt, 0);
    const avgHoldWin = totalBuyWin !== 0 ? totalHoldWin / totalBuyWin : 0;

    const totalHoldLoss = losses.reduce((s, t) => s + (t.days * t.buyAmt), 0);
    const totalBuyLoss = losses.reduce((s, t) => s + t.buyAmt, 0);
    const avgHoldLoss = totalBuyLoss !== 0 ? totalHoldLoss / totalBuyLoss : 0;

    // -----------------------------------------
    // OTHER STANDARD STATS
    // -----------------------------------------

    const winRate = closed.length ? (wins.length / closed.length) * 100 : 0;

    const avgPnLWin = wins.length ? wins.reduce((s, t) => s + t.pnl, 0) / wins.length : 0;
    const avgPnLLoss = losses.length ? Math.abs(losses.reduce((s, t) => s + t.pnl, 0) / losses.length) : 0;

    const rr = avgPnLLoss !== 0 ? avgPnLWin / avgPnLLoss : 0;

    const totalPnl = closed.reduce((s, t) => s + t.pnl, 0);

    return {
        totalPnl,
        avgGain,
        avgLoss,
        winRate,
        rr,
        avgHoldWin,
        avgHoldLoss,
        closed,
        wins,
        losses
    };
}
function calcStats(trades) {
    return calcStatsFromRows(buildTradeRows(trades));
}
function useViewportBelow(maxWidth) {
    const getMatch = () =>
        typeof window !== "undefined" ? window.innerWidth <= maxWidth : false;

    const [matches, setMatches] = useState(getMatch);

    useEffect(() => {
        if (typeof window === "undefined") return undefined;
        const onResize = () => setMatches(getMatch());
        onResize();
        window.addEventListener("resize", onResize);
        return () => window.removeEventListener("resize", onResize);
    }, [maxWidth]);

    return matches;
}

