function RatiosTab({ data, sharedTtmCol, livePrice, T }) {
    const [ratioSubTab, setRatioSubTab] = useState("margin");
    const [roaExpanded, setRoaExpanded] = useState(true);
    const [roeExpanded, setRoeExpanded] = useState(true);
    const [roceExpanded, setRoceExpanded] = useState(true);
    const [deExpanded, setDeExpanded] = useState(true);

    // Historical FY-end prices for Valuation tab: { "2025-03-31": 2367.3, ... }
    const [histPrices, setHistPrices] = useState({});
    const [histLoading, setHistLoading] = useState(false);

    // Load FY-end prices: DB first (instant), fallback to Yahoo Finance
    useEffect(() => {
        if (ratioSubTab !== "valuation" || !data) return;
        const periods = (data.incAnn || []).map(p => p._period).filter(Boolean);
        if (!periods.length) return;
        const alreadyFetched = periods.every(p => histPrices[p] !== undefined);
        if (alreadyFetched) return;

        setHistLoading(true);
        const ticker = data._sym;
        const oldest = periods.reduce((a, b) => a < b ? a : b).slice(0, 10);

        // Extract closest price on or before each FY-end from a sorted-desc rows array
        // Slice both sides to 10 chars (YYYY-MM-DD) to avoid timestamp vs date mismatch
        const extractFromRows = (rows) => {
            const out = {};
            periods.forEach(period => {
                const targetDate = period.slice(0, 10);
                const match = rows.find(r =>
                    r.date && String(r.date).slice(0, 10) <= targetDate && r.close != null);
                out[period] = match ? Number(Number(match.close).toFixed(2)) : null;
            });
            return out;
        };

        // Extract from Yahoo timestamps/closes arrays
        const extractFromYahoo = (timestamps, closes) => {
            const out = {};
            periods.forEach(period => {
                const targetTs = new Date(period).getTime() / 1000 + 86400;
                let best = null;
                for (let i = 0; i < timestamps.length; i++) {
                    if (timestamps[i] <= targetTs && closes[i] != null) best = closes[i];
                }
                out[period] = best ? Number(best.toFixed(2)) : null;
            });
            return out;
        };

        (async () => {
            //  Step 1: Try Supabase stock_prices table 
            try {
                const url = `${SUPABASE_URL}/rest/v1/stock_prices`
                    + `?ticker=eq.${encodeURIComponent(ticker)}`
                    + `&date=gte.${oldest}&order=date.desc&limit=500`;
                const r = await fetch(url, {
                    headers: { "apikey": SUPABASE_ANON_KEY, "Authorization": `Bearer ${SUPABASE_ANON_KEY}` },
                    signal: AbortSignal.timeout(5000),
                });
                if (r.ok) {
                    const rows = await r.json();
                    if (rows.length) {
                        const out = extractFromRows(rows);
                        const allFound = periods.every(p => out[p] != null);
                        //  Use DB prices immediately whether full or partial hit
                        // Missing periods will show "" rather than triggering slow Yahoo fetch
                        setHistPrices(out);
                        setHistLoading(false);
                        if (allFound) return; // all found  fully done
                        // Some periods missing from DB  still try Yahoo to fill gaps
                        // but pre-populate with what we have so table renders instantly
                    }
                }
            } catch { /* fall through to Yahoo */ }

            //  Step 2: Fallback  fetch from Yahoo Finance via proxy 
            try {
                const sym = ticker + ".NS";
                const daysBack = Math.ceil((Date.now() - new Date(oldest).getTime()) / 86400000) + 10;
                const rangeStr = daysBack > 1825 ? "10y" : daysBack > 730 ? "5y" : "2y";
                const url = `https://query1.finance.yahoo.com/v8/finance/chart/${sym}?interval=1d&range=${rangeStr}`;
                const proxies = [
                    `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`,
                    `https://corsproxy.io/?${encodeURIComponent(url)}`,
                    `https://api.allorigins.win/get?url=${encodeURIComponent(url.replace("query1", "query2"))}`,
                ];

                let timestamps = null, closes = null;
                for (const proxy of proxies) {
                    try {
                        const r = await fetch(proxy, { signal: AbortSignal.timeout(15000) });
                        if (!r.ok) continue;
                        const raw = await r.json();
                        const parsed = raw.contents ? JSON.parse(raw.contents) : raw;
                        const result = parsed?.chart?.result?.[0];
                        if (!result?.timestamp?.length) continue;
                        timestamps = result.timestamp;
                        closes = result.indicators?.quote?.[0]?.close;
                        break;
                    } catch { continue; }
                }

                if (timestamps && closes) {
                    setHistPrices(extractFromYahoo(timestamps, closes));
                    setHistLoading(false);
                    return;
                }
            } catch { /* ignore */ }

            // Both failed
            const nulls = {};
            periods.forEach(p => { nulls[p] = null; });
            setHistPrices(nulls);
            setHistLoading(false);
        })();
    }, [ratioSubTab, data?._sym]);

    const ratioTabs = [
        { id: "margin", label: "Margin Ratios" },
        { id: "return", label: "Return Ratios" },
        { id: "liquidity", label: "Liquidity Ratios" },
        { id: "leverage", label: "Leverage Ratios" },
        { id: "turnover", label: "Turnover Ratios" },
        { id: "valuation", label: "Valuation Ratios" },
        { id: "growth", label: "Growth Ratios" },
        { id: "cash_conversion", label: "Cash Conversion" },
        { id: "forensic", label: "Forensic Check" },
    ];

    // Helper: Find matching Balance Sheet data for a P&L period
    const getBsForPeriod = (period) => {
        if (!period) return null;
        const year = period.slice(0, 4);
        return data.bsAnn?.find(b => b._period && b._period.startsWith(year));
    };

    const latestBs = data.bsQtr?.[0] || data.bsAnn?.[0];
    const pctFmt = v => v != null ? `${Number(v).toFixed(2)}%` : "";
    const numFmt = v => v != null ? Number(v).toFixed(2) : "";

    // 1. Margin Ratios Logic  enrich raw incAnn with computed margin keys
    const enrichedAnn = (data.incAnn || []).map(p => {
        const rev = Number(p.Revenue);
        const ebitda = p.EBITDA != null
            ? Number(p.EBITDA)
            : (p.EBIT != null && p.Depreciation != null)
                ? Number(p.EBIT) + Number(p.Depreciation) : null;
        return {
            ...p,
            _gpm: (rev && p.GrossProfit != null) ? (Number(p.GrossProfit) / rev * 100).toFixed(2) + "%" : "",
            _ebitdam: (rev && ebitda != null) ? (ebitda / rev * 100).toFixed(2) + "%" : "",
            _ebitm: (rev && p.EBIT != null) ? (Number(p.EBIT) / rev * 100).toFixed(2) + "%" : "",
            _npm: (rev && p.NetIncome != null) ? (Number(p.NetIncome) / rev * 100).toFixed(2) + "%" : "",
        };
    });

    const passthroughFmt = v => v != null ? v : "";
    const marginRows = [
        { key: "_gpm", label: "GPM %", fmt: passthroughFmt },
        { key: "_ebitdam", label: "EBITDA Margin %", fmt: passthroughFmt },
        { key: "_ebitm", label: "EBIT Margin %", fmt: passthroughFmt },
        { key: "_npm", label: "PAT Margin %", fmt: passthroughFmt },
    ];

    // 2. Return Ratios Logic (Du-Pont RoE + Du-Pont ROCE)
    // CE formula: (TotalEquity + TotalDebt) - CashAndShortTerm - LongTermInvestments
    // Annual periods  matching annual BS; TTM  latest quarterly BS where data is not blank
    const calcCE = (bs) => {
        if (!bs) return null;
        const equity = bs.TotalEquity ?? bs.StockholderEquity ?? null;
        const debt = bs.TotalDebt ?? ((bs.BorrowingsCurrent ?? 0) + (bs.LongTermDebt ?? 0));
        const cash = bs.CashAndShortTerm ?? bs.Cash ?? 0;
        const ltInv = bs.LongTermInvestments ?? 0;
        if (equity == null) return null;
        return (equity + debt) - cash - ltInv;
    };

    // Find latest quarterly BS where key field is not null (BS has alternating blank quarters)
    const latestQtrBsWith = (key) =>
        (data.bsQtr || []).find(b => b[key] != null) || null;

    const latestQtrBsForCE = latestQtrBsWith("TotalEquity") || latestQtrBsWith("StockholderEquity");
    const latestQtrBsForAssets = latestQtrBsWith("TotalAssets");
    const ttmCE = calcCE(latestQtrBsForCE);

    const annualPeriods = (data.incAnn || []).map(p => {
        const bs = getBsForPeriod(p._period);       // matching annual BS for this year
        const npm = (p.Revenue && p.NetIncome != null) ? (p.NetIncome / p.Revenue) : null;
        const assetTurns = (p.Revenue && bs?.TotalAssets) ? (p.Revenue / bs.TotalAssets) : null;
        const finLev = (bs?.TotalAssets && bs?.StockholderEquity) ? (bs.TotalAssets / bs.StockholderEquity) : null;

        const ebitMargin = (p.Revenue && p.EBIT != null) ? (Number(p.EBIT) / Number(p.Revenue)) : null;
        const ce = calcCE(bs);
        const ceTurnover = (p.Revenue && ce != null && ce !== 0)
            ? (Number(p.Revenue) / ce) : null;

        return {
            ...p,
            _npm_val: npm ? (npm * 100).toFixed(2) + "%" : "",
            _asset_turns: numFmt(assetTurns),
            _fin_lev: numFmt(finLev),
            _roa: (npm && assetTurns)
                ? ((npm * assetTurns) * 100).toFixed(2) + "%" : "",
            _roe: (npm && assetTurns && finLev)
                ? ((npm * assetTurns * finLev) * 100).toFixed(2) + "%" : "",
            _ebit_margin: ebitMargin ? (ebitMargin * 100).toFixed(2) + "%" : "",
            _ce_turnover: numFmt(ceTurnover),
            _roce: (ebitMargin && ceTurnover)
                ? ((ebitMargin * ceTurnover) * 100).toFixed(2) + "%" : "",
        };
    });

    // TTM ratios  use TTM P&L + latest non-blank quarterly BS
    const ttmRevenue = sharedTtmCol?.Revenue ?? null;
    const ttmNetIncome = sharedTtmCol?.NetIncome ?? null;
    const ttmEbit = sharedTtmCol?.EBIT ?? null;

    // Asset Turns TTM = TTM Revenue / Latest quarterly TotalAssets (non-blank)
    const ttmTotalAssets = latestQtrBsForAssets?.TotalAssets ?? null;
    const ttmAssetTurns = (ttmRevenue && ttmTotalAssets)
        ? numFmt(Number(ttmRevenue) / ttmTotalAssets) : "";

    // Financial Leverage TTM = TotalAssets / StockholderEquity (latest non-blank qtr)
    const ttmStkEq = latestQtrBsForAssets?.StockholderEquity ?? null;
    const ttmFinLev = (ttmTotalAssets && ttmStkEq)
        ? numFmt(ttmTotalAssets / ttmStkEq) : "";

    // NPM TTM
    const ttmNpm = (ttmRevenue && ttmNetIncome != null)
        ? (Number(ttmNetIncome) / Number(ttmRevenue) * 100).toFixed(2) + "%" : "";

    // RoE TTM = NPM * Asset Turns * Financial Leverage
    const ttmNpmN = (ttmRevenue && ttmNetIncome != null)
        ? Number(ttmNetIncome) / Number(ttmRevenue) : null;
    const ttmAssetN = (ttmRevenue && ttmTotalAssets) ? Number(ttmRevenue) / ttmTotalAssets : null;
    const ttmFinLevN = (ttmTotalAssets && ttmStkEq) ? ttmTotalAssets / ttmStkEq : null;
    const ttmRoe = (ttmNpmN && ttmAssetN && ttmFinLevN)
        ? (ttmNpmN * ttmAssetN * ttmFinLevN * 100).toFixed(2) + "%" : "";

    // EBIT Margin TTM
    const ttmEbitMarginN = (ttmRevenue && ttmEbit != null)
        ? Number(ttmEbit) / Number(ttmRevenue) : null;
    const ttmEbitMarginStr = ttmEbitMarginN != null
        ? (ttmEbitMarginN * 100).toFixed(2) + "%" : "";

    // CE Turnover TTM = TTM Revenue / CE (latest non-blank qtr)
    const ttmCeTurnover = (ttmRevenue && ttmCE != null && ttmCE !== 0)
        ? numFmt(Number(ttmRevenue) / ttmCE) : "";

    // ROCE TTM = EBIT Margin * CE Turnover
    const ttmCeTurnoverN = (ttmRevenue && ttmCE != null && ttmCE !== 0)
        ? Number(ttmRevenue) / ttmCE : null;
    const ttmRoce = (ttmEbitMarginN && ttmCeTurnoverN)
        ? (ttmEbitMarginN * ttmCeTurnoverN * 100).toFixed(2) + "%" : "";

    // Build TTM column for return ratios table
    const ttmNpmN2 = (ttmRevenue && ttmNetIncome != null) ? Number(ttmNetIncome) / Number(ttmRevenue) : null;
    const ttmAssetN2 = (ttmRevenue && ttmTotalAssets) ? Number(ttmRevenue) / ttmTotalAssets : null;
    const ttmRoa = (ttmNpmN2 && ttmAssetN2)
        ? (ttmNpmN2 * ttmAssetN2 * 100).toFixed(2) + "%" : "";

    const roceTtmCol = sharedTtmCol ? {
        ...sharedTtmCol,
        _npm_val: ttmNpm,
        _asset_turns: ttmAssetTurns,
        _fin_lev: ttmFinLev,
        _roa: ttmRoa,
        _roe: ttmRoe,
        _ebit_margin: ttmEbitMarginStr,
        _ce_turnover: ttmCeTurnover,
        _roce: ttmRoce,
    } : null;

    const allReturnRows = [
        { key: "_roa", dataKey: "_roa", label: "Du-Pont RoA", fmt: v => v, parent: "roa" },
        { key: "roa__npm_val", dataKey: "_npm_val", label: "NPM (Net Profit Margin)", fmt: v => v, indent: 1, group: "roa" },
        { key: "roa__asset_turns", dataKey: "_asset_turns", label: "Asset Turns", fmt: v => v, indent: 1, group: "roa" },
        { key: "_roe", dataKey: "_roe", label: "Du-Pont RoE", fmt: v => v, parent: "roe" },
        { key: "roe__npm_val", dataKey: "_npm_val", label: "NPM (Net Profit Margin)", fmt: v => v, indent: 1, group: "roe" },
        { key: "roe__asset_turns", dataKey: "_asset_turns", label: "Asset Turns", fmt: v => v, indent: 1, group: "roe" },
        { key: "roe__fin_lev", dataKey: "_fin_lev", label: "Financial Leverage", fmt: v => v, indent: 1, group: "roe" },
        { key: "_roce", dataKey: "_roce", label: "Du-Pont ROCE", fmt: v => v, parent: "roce" },
        { key: "roce__ebit_margin", dataKey: "_ebit_margin", label: "EBIT Margin", fmt: v => v, indent: 1, group: "roce" },
        { key: "roce__ce_turnover", dataKey: "_ce_turnover", label: "Capital Employed Turnover", fmt: v => v, indent: 1, group: "roce" },
    ];

    const makeChevron = (expanded, toggle, title) => (
        <span onClick={toggle}
            style={{ cursor: "pointer", userSelect: "none", display: "flex", alignItems: "center", gap: 6 }}>
            {title}
        </span>
    );

    const returnRows = allReturnRows.filter(r =>
        (!r.group) ||
        (r.group === "roa" && roaExpanded) ||
        (r.group === "roe" && roeExpanded) ||
        (r.group === "roce" && roceExpanded)
    ).map(r => {
        if (r.parent === "roa") return { ...r, label: makeChevron(roaExpanded, () => setRoaExpanded(v => !v), "Du-Pont RoA") };
        if (r.parent === "roe") return { ...r, label: makeChevron(roeExpanded, () => setRoeExpanded(v => !v), "Du-Pont RoE") };
        if (r.parent === "roce") return { ...r, label: makeChevron(roceExpanded, () => setRoceExpanded(v => !v), "Du-Pont ROCE") };
        return r;
    });

    return (
        <div style={{ display: "flex", flexDirection: "column", flex: 1 }}>
            <div className="fin-subtabs">
                {ratioTabs.map(tab => (
                    <button
                        key={tab.id}
                        className={`fin-subtab${ratioSubTab === tab.id ? " active" : ""}`}
                        onClick={() => setRatioSubTab(tab.id)}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Sub-Tab Content */}
            <div style={{ flex: 1, overflowY: "auto" }}>
                {ratioSubTab === "margin" && (
                    <MarginRatiosTab
                        enrichedAnn={enrichedAnn}
                        marginRows={marginRows}
                        sharedTtmCol={sharedTtmCol}
                        T={T}
                    />
                )}
                {ratioSubTab === "return" && (
                    <FinTable
                        title="Return Ratios (Du-Pont)"
                        rows={returnRows}
                        cols={["Metric"]}
                        data={annualPeriods}
                        ttmCol={roceTtmCol}
                        highlightRows={["_roa", "_roe", "_roce"]}
                        T={T}
                    />
                )}
                {ratioSubTab === "liquidity" && (() => {
                    // Helper: latest non-null quarter for a given key
                    const latestQtrWith = (key) =>
                        (data.bsQtr || []).find(b => b[key] != null) || null;

                    // Annual liquidity data
                    const liquidityAnn = (data.bsAnn || []).map(bs => {
                        const ca = bs.TotalCurrentAssets ?? null;
                        const cl = bs.TotalCurrentLiab ?? null;
                        const inv = bs.Inventories ?? null;
                        return {
                            _period: bs._period,
                            _current_ratio: (ca != null && cl != null && cl !== 0)
                                ? (ca / cl).toFixed(2) : "",
                            _quick_ratio: (ca != null && cl != null && cl !== 0)
                                ? ((ca - (inv ?? 0)) / cl).toFixed(2) : "",
                        };
                    });

                    // TTM: latest non-null quarter
                    const qtrForCA = latestQtrWith("TotalCurrentAssets");
                    const qtrForCL = latestQtrWith("TotalCurrentLiab");
                    const ttmCA = qtrForCA?.TotalCurrentAssets ?? null;
                    const ttmCL = qtrForCL?.TotalCurrentLiab ?? null;
                    const ttmInv = latestQtrWith("Inventories")?.Inventories ?? 0;
                    const ttmLiqCol = (ttmCA != null && ttmCL != null && ttmCL !== 0) ? {
                        _current_ratio: (ttmCA / ttmCL).toFixed(2),
                        _quick_ratio: ((ttmCA - ttmInv) / ttmCL).toFixed(2),
                    } : null;

                    const liquidityRows = [
                        { key: "_current_ratio", label: "Current Ratio", fmt: v => v },
                        { key: "_quick_ratio", label: "Quick Ratio", fmt: v => v },
                    ];

                    return (
                        <FinTable
                            title="Liquidity Ratios (Annual & TTM)"
                            rows={liquidityRows}
                            cols={["Metric"]}
                            data={liquidityAnn}
                            ttmCol={ttmLiqCol}
                        />
                    );
                })()}
                {ratioSubTab === "leverage" && (() => {
                    const calcLev = (bs) => {
                        if (!bs) return { _de: "", _ltde: "", _stde: "" };
                        const eq = bs.TotalEquity ?? bs.StockholderEquity ?? null;
                        const ltd = bs.LongTermDebt ?? 0;
                        const std = bs.BorrowingsCurrent ?? 0;
                        if (!eq || eq === 0) return { _de: "", _ltde: "", _stde: "" };
                        return {
                            _de: ((ltd + std) / eq).toFixed(2),
                            _ltde: (ltd / eq).toFixed(2),
                            _stde: (std / eq).toFixed(2),
                        };
                    };

                    // Match annual P&L for interest coverage
                    const getIncForPeriod = (period) => {
                        if (!period) return null;
                        const year = period.slice(0, 4);
                        return (data.incAnn || []).find(p => p._period && p._period.startsWith(year));
                    };

                    const calcICR = (ebit, interest) => {
                        if (ebit == null || !interest || interest === 0) return "";
                        return (Math.abs(Number(ebit)) / Math.abs(Number(interest))).toFixed(2);
                    };

                    const leverageAnn = (data.bsAnn || []).map(bs => {
                        const inc = getIncForPeriod(bs._period);
                        return {
                            _period: bs._period,
                            ...calcLev(bs),
                            _icr: calcICR(inc?.EBIT, inc?.InterestExpense),
                        };
                    });

                    const ttmBs = (data.bsQtr || []).find(b => (b.TotalEquity ?? b.StockholderEquity) != null) || null;
                    const ttmLevCol = {
                        ...calcLev(ttmBs),
                        _icr: calcICR(sharedTtmCol?.EBIT, sharedTtmCol?.InterestExpense),
                    };

                    const allLevRows = [
                        { key: "_de", label: "Debt / Equity", fmt: v => v, parent: "de" },
                        { key: "_ltde", label: "LT Debt / Equity", fmt: v => v, indent: 1, group: "de" },
                        { key: "_stde", label: "ST Debt / Equity", fmt: v => v, indent: 1, group: "de" },
                        { key: "_icr", label: "Interest Coverage Ratio", fmt: v => v },
                    ];

                    const levRows = allLevRows
                        .filter(r => !r.group || (r.group === "de" && deExpanded))
                        .map(r => r.parent === "de" ? {
                            ...r, label: (
                                <span onClick={() => setDeExpanded(v => !v)}
                                    style={{ cursor: "pointer", userSelect: "none", display: "flex", alignItems: "center", gap: 6 }}>
                                    <span style={{
                                        fontSize: 10, display: "inline-block", transition: "transform .15s",
                                        transform: deExpanded ? "rotate(90deg)" : "rotate(0deg)"
                                    }}></span>
                                    Debt / Equity
                                </span>
                            )
                        } : r);

                    return (
                        <FinTable
                            title="Leverage Ratios (Annual & TTM)"
                            rows={levRows}
                            cols={["Metric"]}
                            data={leverageAnn}
                            ttmCol={ttmLevCol}
                            highlightRows={["_de"]}
                        />
                    );
                })()}
                {ratioSubTab === "turnover" && (() => {
                    // Helper: latest non-null quarter for a given key
                    const latestQtrWithTO = (key) =>
                        (data.bsQtr || []).find(b => b[key] != null) || null;

                    // Match annual P&L to annual BS period
                    const getIncForPeriodTO = (period) => {
                        if (!period) return null;
                        const year = period.slice(0, 4);
                        return (data.incAnn || []).find(p => p._period && p._period.startsWith(year));
                    };

                    const turnoverAnn = (data.bsAnn || []).map(bs => {
                        const inc = getIncForPeriodTO(bs._period);
                        const revenue = inc?.Revenue ?? null;
                        const cogs = inc?.COGS ?? null;
                        const assets = bs.TotalAssets ?? null;
                        const inventory = bs.Inventories ?? null;

                        const assetTurn = (revenue && assets)
                            ? (Number(revenue) / Number(assets)).toFixed(2) : "";
                        const invTurn = (cogs && inventory && Number(inventory) !== 0)
                            ? (Number(cogs) / Number(inventory)).toFixed(2) : "";

                        return { _period: bs._period, _asset_turn: assetTurn, _inv_turn: invTurn };
                    });

                    // TTM asset turnover
                    const ttmQtrAssets = latestQtrWithTO("TotalAssets");
                    const ttmAssets = ttmQtrAssets?.TotalAssets ?? null;
                    const ttmRev = sharedTtmCol?.Revenue ?? null;
                    const ttmCogs = sharedTtmCol?.COGS ?? null;
                    const ttmQtrInv = latestQtrWithTO("Inventories");
                    const ttmInv = ttmQtrInv?.Inventories ?? null;

                    const ttmTurnCol = {
                        _asset_turn: (ttmRev && ttmAssets)
                            ? (Number(ttmRev) / Number(ttmAssets)).toFixed(2) : "",
                        _inv_turn: (ttmCogs && ttmInv && Number(ttmInv) !== 0)
                            ? (Number(ttmCogs) / Number(ttmInv)).toFixed(2) : "",
                    };

                    const turnoverRows = [
                        { key: "_asset_turn", label: "Asset Turnover", fmt: v => v },
                        { key: "_inv_turn", label: "Inventory Turnover (x)", fmt: v => v },
                    ];

                    return (
                        <FinTable
                            title="Turnover Ratios (Annual & TTM)"
                            rows={turnoverRows}
                            cols={["Metric"]}
                            data={turnoverAnn}
                            ttmCol={ttmTurnCol}
                        />
                    );
                })()}
                {ratioSubTab === "valuation" && (() => {
                    const curPrice = livePrice?.price ?? data.current_price ?? null;
                    const shares = data.shares_outstanding ?? null;

                    //  Helpers 
                    const getBS = period => (data.bsAnn || []).find(b =>
                        b._period && b._period.slice(0, 4) === period.slice(0, 4)) || null;
                    const getCF = period => (data.cfAnn || []).find(c =>
                        c._period && c._period.slice(0, 4) === period.slice(0, 4)) || null;

                    // Latest quarterly BS row that has a non-null value for a given key
                    const latestQtrBsWith = key =>
                        (data.bsQtr || []).find(b => b[key] != null) || null;

                    // EV components from a BS row (all values already scaled CR)
                    const calcEV = (bs, mcap) => {
                        if (!bs || !mcap) return null;
                        // Total Debt: prefer TotalDebt, else LongTermDebt + BorrowingsCurrent
                        const debt = bs.TotalDebt != null
                            ? Number(bs.TotalDebt)
                            : (Number(bs.LongTermDebt ?? 0) + Number(bs.BorrowingsCurrent ?? 0));
                        // NCI = NonControllingInterest
                        const nci = bs.NonControllingInterest != null ? Number(bs.NonControllingInterest) : 0;
                        // Cash: prefer CashAndShortTerm, else Cash + ShortTermInvestments
                        const cash = bs.CashAndShortTerm != null
                            ? Number(bs.CashAndShortTerm)
                            : (Number(bs.Cash ?? 0) + Number(bs.ShortTermInvestments ?? 0));
                        return mcap + debt + nci - cash; // all in same  scale
                    };

                    // EBITDA from income statement (scaled CR)
                    const calcEBITDA = p => {
                        if (p.EBITDA != null) return Number(p.EBITDA);
                        if (p.EBIT != null && p.Depreciation != null)
                            return Number(p.EBIT) + Number(p.Depreciation);
                        return null;
                    };

                    //  FY annual rows 
                    const valuationAnn = (data.incAnn || []).map(p => {
                        const price = histPrices[p._period] ?? (histLoading ? undefined : null);
                        const isLoading = price === undefined;
                        const ph = "";

                        const eps = p.EPS != null ? Number(p.EPS) : null;
                        const rev = p.Revenue != null ? Number(p.Revenue) : null;
                        const bs = getBS(p._period);
                        const cf = getCF(p._period);

                        // MCap (scaled, same units as BS values)
                        const mcap = (price && shares) ? price * shares : null;

                        // P/E
                        const pe = isLoading ? ph : (price && eps && eps !== 0)
                            ? (price / eps).toFixed(1) : "";

                        // P/S
                        const ps = isLoading ? ph : (mcap && rev && rev !== 0)
                            ? (mcap / rev).toFixed(2) : "";

                        // P/B
                        const bvRaw = (bs?.TotalAssets != null && bs?.TotalLiabilities != null)
                            ? Number(bs.TotalAssets) - Number(bs.TotalLiabilities) : null;
                        const pb = isLoading ? ph : (mcap && bvRaw && bvRaw !== 0)
                            ? (mcap / bvRaw).toFixed(2) : "";

                        // MCap Cr
                        const mcapCr = isLoading ? ph : mcap ? (mcap / CR).toFixed(0) : "";

                        // EV/EBITDA
                        const ev = mcap != null ? calcEV(bs, mcap) : null;
                        const ebitda = calcEBITDA(p);
                        const evEbitda = isLoading ? ph : (ev != null && ebitda && ebitda !== 0)
                            ? (ev / ebitda).toFixed(1) : "";

                        // P/OCF = MCap / OperatingCF
                        const ocf = cf?.OperatingCF != null ? Number(cf.OperatingCF) : null;
                        const pOcf = isLoading ? ph : (mcap && ocf && ocf > 0)
                            ? (mcap / ocf).toFixed(1) : "";

                        // P/FCF = MCap / FreeCF  (show  if FCF negative  meaningless multiple)
                        const fcf = cf?.FreeCF != null ? Number(cf.FreeCF) : null;
                        const pFcf = isLoading ? ph : (mcap && fcf && fcf > 0)
                            ? (mcap / fcf).toFixed(1) : "";

                        return {
                            _period: p._period, _mcap: mcapCr, _pe: pe, _ps: ps, _pb: pb,
                            _evEbitda: evEbitda, _pOcf: pOcf, _pFcf: pFcf
                        };
                    });

                    //  TTM column 
                    const ttmMcap = (curPrice && shares) ? curPrice * shares : null;
                    const ttmMcapCr = ttmMcap ? (ttmMcap / CR).toFixed(0) : "";

                    const ttmEps = sharedTtmCol?.EPS ?? null;
                    const ttmRev = sharedTtmCol?.Revenue ?? null;

                    const ttmBsAssets = latestQtrBsWith("TotalAssets");
                    const ttmBsDebt = latestQtrBsWith("TotalDebt") || latestQtrBsWith("LongTermDebt");
                    const ttmBsCash = latestQtrBsWith("CashAndShortTerm") || latestQtrBsWith("Cash");
                    const ttmBsNci = latestQtrBsWith("NonControllingInterest");
                    // Prefer a single row that has all EV components; fall back to separate lookups
                    const ttmBsForEV = ttmBsDebt || ttmBsCash || ttmBsAssets || (data.bsAnn || [])[0] || null;

                    const ttmBV = (ttmBsAssets?.TotalAssets != null && ttmBsAssets?.TotalLiabilities != null)
                        ? Number(ttmBsAssets.TotalAssets) - Number(ttmBsAssets.TotalLiabilities) : null;

                    // Latest annual CF (cfQtr is empty  use most recent cfAnn)
                    const latestCF = (data.cfAnn || [])[data.cfAnn?.length - 1] || null;
                    const ttmOcf = latestCF?.OperatingCF != null ? Number(latestCF.OperatingCF) : null;
                    const ttmFcf = latestCF?.FreeCF != null ? Number(latestCF.FreeCF) : null;

                    const ttmPe = (curPrice && ttmEps && Number(ttmEps) !== 0)
                        ? (curPrice / Number(ttmEps)).toFixed(1) : "";
                    const ttmPs = (ttmMcap && ttmRev && Number(ttmRev) !== 0)
                        ? (ttmMcap / Number(ttmRev)).toFixed(2) : "";
                    const ttmPb = (ttmMcap && ttmBV && ttmBV !== 0)
                        ? (ttmMcap / ttmBV).toFixed(2) : "";

                    const ttmEV = ttmMcap != null ? calcEV(ttmBsForEV, ttmMcap) : null;
                    const ttmEbitda = sharedTtmCol ? calcEBITDA(sharedTtmCol) : null;
                    const ttmEvEbitda = (ttmEV != null && ttmEbitda && ttmEbitda !== 0)
                        ? (ttmEV / ttmEbitda).toFixed(1) : "";
                    const ttmPOcf = (ttmMcap && ttmOcf && ttmOcf > 0)
                        ? (ttmMcap / ttmOcf).toFixed(1) : "";
                    const ttmPFcf = (ttmMcap && ttmFcf && ttmFcf > 0)
                        ? (ttmMcap / ttmFcf).toFixed(1) : "";

                    const valRows = [
                        { key: "_mcap", label: "Market Cap ( Cr)", fmt: v => v },
                        { key: "_pe", label: "P/E Ratio", fmt: v => v },
                        { key: "_ps", label: "P/S Ratio", fmt: v => v },
                        { key: "_pb", label: "P/B Ratio", fmt: v => v },
                        { key: "_evEbitda", label: "EV / EBITDA", fmt: v => v },
                        { key: "_pOcf", label: "Price / OCF", fmt: v => v },
                        { key: "_pFcf", label: "Price / FCF", fmt: v => v },
                    ];

                    return (
                        <>
                            {histLoading && (
                                <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "6px 18px", fontSize: 11, color: T.muted }}>
                                    <span style={{ display: "inline-block", width: 10, height: 10, border: `1.5px solid ${T.green}`, borderTopColor: "transparent", borderRadius: "50%", animation: "spin 0.7s linear infinite" }} />
                                    Loading historical prices
                                </div>
                            )}
                            <FinTable
                                title="Valuation Ratios"
                                rows={valRows}
                                cols={["Metric"]}
                                data={valuationAnn}
                                ttmCol={{
                                    _mcap: ttmMcapCr, _pe: ttmPe, _ps: ttmPs, _pb: ttmPb,
                                    _evEbitda: ttmEvEbitda, _pOcf: ttmPOcf, _pFcf: ttmPFcf
                                }}
                            />
                        </>
                    );
                })()}

                {ratioSubTab === "growth" && <GrowthSubTab data={data} sharedTtmCol={sharedTtmCol} T={T} />}

                {ratioSubTab === "cash_conversion" && (() => {
                    // Helper: latest non-null quarter BS for a given key
                    const latestQtrWith = (key) =>
                        (data.bsQtr || []).find(b => b[key] != null && Number(b[key]) !== 0) || null;

                    // Annual cash conversion data
                    const cashConvAnn = (data.incAnn || []).map(inc => {
                        const period = inc._period;
                        const year = period ? period.slice(0, 4) : null;
                        const bs = year ? (data.bsAnn || []).find(b => b._period && b._period.startsWith(year)) : null;

                        const revenue = inc.Revenue != null ? Number(inc.Revenue) : null;
                        const cogs = inc.COGS != null ? Number(inc.COGS) : null;
                        const trRec = bs?.TradeReceivables ?? bs?.["AccountsReceivable-TradeNet"] ?? null;
                        const inv = bs?.Inventories ?? null;
                        const trPay = bs?.TradePayables ?? null;

                        const debtorDays = (revenue && trRec != null && revenue !== 0) ? (365 * Number(trRec) / revenue) : null;
                        const inventDays = (cogs && inv != null && cogs !== 0) ? (365 * Number(inv) / cogs) : null;
                        const payableDays = (cogs && trPay != null && cogs !== 0) ? (365 * Number(trPay) / cogs) : null;
                        const ccc = (debtorDays != null && inventDays != null && payableDays != null)
                            ? debtorDays + inventDays - payableDays : null;

                        return {
                            _period: period,
                            _debtor_days: debtorDays != null ? debtorDays.toFixed(1) : "",
                            _invent_days: inventDays != null ? inventDays.toFixed(1) : "",
                            _payable_days: payableDays != null ? payableDays.toFixed(1) : "",
                            _ccc: ccc != null ? ccc.toFixed(1) : "",
                        };
                    });

                    // TTM column
                    const ttmRec = latestQtrWith("TradeReceivables")?.TradeReceivables
                        ?? latestQtrWith("AccountsReceivable-TradeNet")?.["AccountsReceivable-TradeNet"] ?? null;
                    const ttmInv = latestQtrWith("Inventories")?.Inventories ?? null;
                    const ttmPay = latestQtrWith("TradePayables")?.TradePayables ?? null;
                    const ttmRev = sharedTtmCol?.Revenue ?? null;
                    const ttmCogs = sharedTtmCol?.COGS ?? null;

                    const ttmDebtorDays = (ttmRev && ttmRec != null && Number(ttmRev) !== 0) ? (365 * Number(ttmRec) / Number(ttmRev)) : null;
                    const ttmInventDays = (ttmCogs && ttmInv != null && Number(ttmCogs) !== 0) ? (365 * Number(ttmInv) / Number(ttmCogs)) : null;
                    const ttmPayableDays = (ttmCogs && ttmPay != null && Number(ttmCogs) !== 0) ? (365 * Number(ttmPay) / Number(ttmCogs)) : null;
                    const ttmCcc = (ttmDebtorDays != null && ttmInventDays != null && ttmPayableDays != null)
                        ? ttmDebtorDays + ttmInventDays - ttmPayableDays : null;

                    const ttmCashConvCol = {
                        _debtor_days: ttmDebtorDays != null ? ttmDebtorDays.toFixed(1) : "",
                        _invent_days: ttmInventDays != null ? ttmInventDays.toFixed(1) : "",
                        _payable_days: ttmPayableDays != null ? ttmPayableDays.toFixed(1) : "",
                        _ccc: ttmCcc != null ? ttmCcc.toFixed(1) : "",
                    };

                    const cashConvRows = [
                        { key: "_debtor_days", label: "Debtor Days", fmt: v => v },
                        { key: "_invent_days", label: "Inventory Days", fmt: v => v },
                        { key: "_payable_days", label: "Payable Days", fmt: v => v },
                        { key: "_ccc", label: "Cash Conversion Cycle", fmt: v => v },
                    ];

                    return (
                        <CashConversionTab
                            cashConvAnn={cashConvAnn}
                            cashConvRows={cashConvRows}
                            ttmCashConvCol={ttmCashConvCol}
                            T={T}
                        />
                    );
                })()}

                {ratioSubTab === "forensic" && (() => {
                    //  Helpers 
                    const ratioX = (num, den) => (num != null && den != null && Number(den) !== 0)
                        ? (Number(num) / Number(den)).toFixed(2) + "x" : "";
                    const ratioPct = (num, den) => (num != null && den != null && Number(den) !== 0)
                        ? (Number(num) / Number(den) * 100).toFixed(2) + "%" : "";
                    const getEbitda = (p) => p?.EBITDA != null
                        ? Number(p.EBITDA)
                        : (p?.EBIT != null && p?.Depreciation != null ? Number(p.EBIT) + Number(p.Depreciation) : null);

                    //  FY data: one column per annual period 
                    // Match incAnn  cfAnn  bsAnn by year
                    const incAnn = data.incAnn || [];
                    const getCFForPeriod = (period) => (data.cfAnn || []).find(c => c._period && c._period.slice(0, 4) === period.slice(0, 4)) || null;
                    const getBSForPeriod = (period) => (data.bsAnn || []).find(b => b._period && b._period.slice(0, 4) === period.slice(0, 4)) || null;

                    const forensicAnn = incAnn.map(p => {
                        const cf = getCFForPeriod(p._period);
                        const bs = getBSForPeriod(p._period);
                        const cfo = cf?.OperatingCF != null ? Number(cf.OperatingCF) : null;
                        const pat = p.NetIncome != null ? Number(p.NetIncome) : null;
                        const ebitda = getEbitda(p);
                        const depr = p.Depreciation != null ? Number(p.Depreciation) : null;
                        const rev = p.Revenue != null ? Number(p.Revenue) : null;
                        const rec = bs?.TradeReceivables ?? bs?.["AccountsReceivable-TradeNet"] ?? null;
                        const inv = bs?.Inventories ?? null;
                        return {
                            _period: p._period,
                            _cfo_pat: ratioX(cfo, pat),
                            _cfo_ebitda: ratioX(cfo, ebitda),
                            _depr_sales: ratioPct(depr, rev),
                            _rec_sales: ratioPct(rec, rev),
                            _inv_sales: ratioPct(inv, rev),
                        };
                    });

                    //  TTM column 
                    // CFO = latest annual OperatingCF (most recent CF statement)
                    const latestCFAnn = (data.cfAnn || []).length ? data.cfAnn[data.cfAnn.length - 1] : null;
                    const ttmCfo = latestCFAnn?.OperatingCF != null ? Number(latestCFAnn.OperatingCF) : null;

                    // PAT / EBITDA / Depreciation / Sales = sum of last 4 income quarters
                    const incQtr4 = (data.incQtr || []).slice(0, 4);
                    const sumQtr = (key) => {
                        const vals = incQtr4.map(q => q[key]).filter(v => v != null);
                        return vals.length ? vals.reduce((s, v) => s + Number(v), 0) : null;
                    };
                    const ttmPat = sumQtr("NetIncome");
                    const ttmRev = sharedTtmCol?.Revenue != null ? Number(sharedTtmCol.Revenue) : sumQtr("Revenue");
                    const ttmDepr = sumQtr("Depreciation");
                    const ttmEbitda = sharedTtmCol ? getEbitda(sharedTtmCol) : null;

                    // Receivables & Inventory: latest non-zero BS value (quarterly first, then annual)
                    const latestQtrWith = (key) =>
                        (data.bsQtr || []).find(b => b[key] != null && Number(b[key]) !== 0) || null;
                    const bsRec = (() => {
                        const q = latestQtrWith("TradeReceivables") || latestQtrWith("AccountsReceivable-TradeNet");
                        if (q) return q.TradeReceivables ?? q["AccountsReceivable-TradeNet"] ?? null;
                        // fallback to annual
                        const a = [...(data.bsAnn || [])].reverse().find(b =>
                            (b.TradeReceivables != null && Number(b.TradeReceivables) !== 0) ||
                            (b["AccountsReceivable-TradeNet"] != null && Number(b["AccountsReceivable-TradeNet"]) !== 0));
                        return a ? (a.TradeReceivables ?? a["AccountsReceivable-TradeNet"] ?? null) : null;
                    })();
                    const bsInv = (() => {
                        const q = latestQtrWith("Inventories");
                        if (q) return q.Inventories;
                        const a = [...(data.bsAnn || [])].reverse().find(b => b.Inventories != null && Number(b.Inventories) !== 0);
                        return a?.Inventories ?? null;
                    })();

                    const forensicTtm = {
                        _cfo_pat: ratioX(ttmCfo, ttmPat),
                        _cfo_ebitda: ratioX(ttmCfo, ttmEbitda),
                        _depr_sales: ratioPct(ttmDepr, ttmRev),
                        _rec_sales: ratioPct(bsRec, ttmRev),
                        _inv_sales: ratioPct(bsInv, ttmRev),
                    };

                    //  Row definitions for FinTable 
                    const forensicRows = [
                        { key: "_cfo_pat", label: "CFO to PAT", fmt: v => v, colorize: false },
                        { key: "_cfo_ebitda", label: "CFO to EBITDA", fmt: v => v, colorize: false },
                        { key: "_depr_sales", label: "Depreciation to Sales", fmt: v => v, colorize: false },
                        { key: "_rec_sales", label: "Receivables to Sales", fmt: v => v, colorize: false },
                        { key: "_inv_sales", label: "Inventory to Sales", fmt: v => v, colorize: false },
                    ];

                    if (!forensicAnn.length) return <div className="fin-empty">No annual data available for {data._sym}</div>;

                    return (
                        <>
                            <FinTable
                                title="Forensic Check (FY & TTM)"
                                cols={["Metric"]}
                                data={forensicAnn}
                                rows={forensicRows}
                                highlightRows={[]}
                                ttmCol={forensicTtm}
                                T={T}
                            />
                            <div style={{ padding: "10px 24px 20px", fontSize: 11, color: T.subtext, lineHeight: 1.8 }}>
                                <strong style={{ color: T.text }}>Notes:</strong>&ensp;
                                CFO = annual cash flow from operations (matched by FY; TTM uses latest annual CF statement)
                                &ensp;&ensp;PAT / EBITDA / Depreciation / Sales = FY annual figures (TTM = sum of last 4 quarters)
                                &ensp;&ensp;Receivables &amp; Inventory = annual BS matched by FY (TTM = latest non-zero BS)
                            </div>
                        </>
                    );
                })()}
            </div>
        </div>
    );
}

