//  Screener Screens  cloud sync (Supabase) 
// Table: screener_screens (id text, user_id uuid, name text, filters jsonb, sort_order int, updated_at timestamptz)
// Primary key (user_id, id); RLS restricts rows to auth.uid() = user_id.
async function _fetchRemoteScreens(sess) {
    if (!sess?.user?.id || !sess?.access_token) return [];
    try {
        const r = await fetch(
            `${SUPABASE_URL}/rest/v1/screener_screens?select=id,name,filters,sort_order&user_id=eq.${sess.user.id}&order=sort_order.asc`,
            { headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${sess.access_token}` } }
        );
        const data = await r.json();
        return Array.isArray(data) ? data : [];
    } catch { return []; }
}
async function _upsertRemoteScreen(sess, screen, order) {
    if (!sess?.user?.id || !sess?.access_token) return;
    try {
        await fetch(`${SUPABASE_URL}/rest/v1/screener_screens?on_conflict=user_id,id`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                apikey: SUPABASE_ANON_KEY,
                Authorization: `Bearer ${sess.access_token}`,
                Prefer: "resolution=merge-duplicates",
            },
            body: JSON.stringify({
                id: screen.id, user_id: sess.user.id, name: screen.name,
                filters: screen.filters || [], sort_order: order,
                updated_at: new Date().toISOString(),
            }),
        });
    } catch { }
}
async function _deleteRemoteScreen(sess, id) {
    if (!sess?.user?.id || !sess?.access_token) return;
    try {
        await fetch(
            `${SUPABASE_URL}/rest/v1/screener_screens?user_id=eq.${sess.user.id}&id=eq.${encodeURIComponent(id)}`,
            { method: "DELETE", headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${sess.access_token}` } }
        );
    } catch { }
}

function makeEmptyFilter() {
    return { id: Date.now() + Math.random(), col: "market_cap_cr", op: ">", val: "", valType: "number", rhsCol: "net_block_1y", rhsMul: "1" };
}

function applyFilters(rows, filters) {
    return rows.filter(row =>
        filters.every(f => {
            const rv = row[f.col];
            if (rv == null) return false;
            const lhs = Number(rv);
            if (isNaN(lhs)) return true;

            let thresh;
            if (f.valType === "column") {
                // RHS = multiplier  column value
                const rhsVal = row[f.rhsCol];
                if (rhsVal == null) return false;
                const mul = parseFloat(f.rhsMul) || 1;
                thresh = mul * Number(rhsVal);
                if (isNaN(thresh)) return false;
            } else {
                if (!f.val && f.val !== 0) return true; // blank = skip
                thresh = Number(f.val);
                if (isNaN(thresh)) return true;
            }

            switch (f.op) {
                case ">": return lhs > thresh;
                case "<": return lhs < thresh;
                case ">=": return lhs >= thresh;
                case "<=": return lhs <= thresh;
                case "=": return Math.abs(lhs - thresh) < 0.001;
                case "!=": return Math.abs(lhs - thresh) >= 0.001;
                default: return true;
            }
        })
    );
}

//  module-level cache so navigating away & back is instant 
let _screenerCache = null;
let _screenerCacheTime = null;
let _screenerCacheLoadedAt = null;
let _screenerPrefetchPromise = null;
const _LS_SCREENER_KEY = "te_screener_cache_v2";
const _SCREENER_CACHE_TTL_MS = 30 * 60 * 1000; // 30 min memory fresh window
const _LS_SCREENER_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 h stale-but-usable window

//  Nifty 500 constituent tickers cache 
let _nifty500Cache = null; // Set<string> of tickers, null = not loaded yet

//  Breadth module caches  survive tab navigation 
//  localStorage persistence helpers 
const _LS_BREADTH_KEY = "te_breadth_cache_v5";
const _LS_SECTOR_KEY = "te_sector_cache_v3";
const _LS_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 h  localStorage TTL (stale-but-usable)

function _lsWrite(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* quota exceeded  ignore */ }
}
function _lsRead(key) {
    try { const s = localStorage.getItem(key); return s ? JSON.parse(s) : null; } catch { return null; }
}

function _seedScreenerCache() {
    const saved = _lsRead(_LS_SCREENER_KEY);
    if (!saved || !saved.loadedAt || (Date.now() - saved.loadedAt) > _LS_SCREENER_MAX_AGE_MS) return;
    if (!Array.isArray(saved.rows) || saved.rows.length === 0) return;
    _screenerCache = saved.rows;
    _screenerCacheLoadedAt = saved.loadedAt;
    _screenerCacheTime = saved.lastRefresh || new Date(saved.loadedAt).toLocaleTimeString("en-IN");
}

function _writeScreenerCache(rows) {
    if (!Array.isArray(rows) || rows.length === 0) return;
    const payload = {
        rows,
        loadedAt: Date.now(),
        lastRefresh: new Date().toLocaleTimeString("en-IN"),
    };
    _screenerCache = payload.rows;
    _screenerCacheLoadedAt = payload.loadedAt;
    _screenerCacheTime = payload.lastRefresh;
    _lsWrite(_LS_SCREENER_KEY, payload);
}

function _isScreenerCacheFresh() {
    return !!(_screenerCacheLoadedAt && (Date.now() - _screenerCacheLoadedAt) < _SCREENER_CACHE_TTL_MS);
}

// Parses "MMM YYYY"-style quarter labels (e.g. "Jun 2023") into a comparable timestamp.
function _parseQtrDate(label) {
    if (!label) return 0;
    const t = Date.parse(label);
    return isNaN(t) ? 0 : t;
}
// Given a company_shareholding row's `quarterly` jsonb array, returns the single
// most recent quarter's entry (handles both pre-parsed arrays and JSON strings).
function _latestShareholdingQuarter(quarterly) {
    let arr = quarterly;
    if (typeof arr === "string") { try { arr = JSON.parse(arr); } catch { arr = null; } }
    if (!Array.isArray(arr) || arr.length === 0) return null;
    return arr.reduce((latest, q) => (!latest || _parseQtrDate(q?.date) > _parseQtrDate(latest?.date)) ? q : latest, null);
}

async function _fetchScreenerRows() {
    const PAGE = 1000;
    const headers = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}`, Prefer: "count=exact" };
    const base = `${SUPABASE_URL}/rest/v1/stock_ratios?select=*&order=market_cap_cr.desc.nullslast&limit=${PAGE}`;
    const firstRes = await fetch(`${base}&offset=0`, { headers });
    if (!firstRes.ok) throw new Error(`HTTP ${firstRes.status}`);
    const totalCount = parseInt(firstRes.headers.get("content-range")?.split("/")[1] || "0");
    const firstPage = await firstRes.json();
    const offsets = [];
    for (let offset = PAGE; offset < totalCount; offset += PAGE) offsets.push(offset);
    const restPages = await Promise.all(
        offsets.map(offset =>
            fetch(`${base}&offset=${offset}`, { headers }).then(r => r.ok ? r.json() : [])
        )
    );
    const all = [firstPage, ...restPages].flat().filter(Boolean);

    let enriched = all;
    try {
        const cfHeaders = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` };
        const cfBase = `${SUPABASE_URL}/rest/v1/company_financials?select=ticker,nse_code&limit=10000`;
        const cfRes = await fetch(cfBase, { headers: cfHeaders });
        if (cfRes.ok) {
            const cfRows = await cfRes.json();
            const cfMap = new Map();
            for (const r of cfRows) if (r.ticker) cfMap.set(r.ticker.trim().toUpperCase(), r);
            enriched = all.filter(row => {
                const t = (row.ticker || "").trim().toUpperCase();
                if (/^\d+$/.test(t)) return false;
                const cf = cfMap.get(t);
                const nse = (cf?.nse_code || "").trim();
                if (cf && !nse) return false;
                row.displayTicker = nse || row.ticker || "";
                return true;
            });
        }
    } catch (_) {
        enriched = all;
    }

    // Promoter %/FII %/DII % should reflect the latest quarterly shareholding filing,
    // not whatever (often stale/blank) snapshot lives on stock_ratios directly.
    try {
        const shHeaders = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}`, Prefer: "count=exact" };
        const shBase = `${SUPABASE_URL}/rest/v1/company_shareholding?select=ticker,quarterly&limit=${PAGE}`;
        const shFirstRes = await fetch(`${shBase}&offset=0`, { headers: shHeaders });
        if (shFirstRes.ok) {
            const shTotal = parseInt(shFirstRes.headers.get("content-range")?.split("/")[1] || "0");
            const shFirstPage = await shFirstRes.json();
            const shOffsets = [];
            for (let offset = PAGE; offset < shTotal; offset += PAGE) shOffsets.push(offset);
            const shRestPages = await Promise.all(
                shOffsets.map(offset => fetch(`${shBase}&offset=${offset}`, { headers: shHeaders }).then(r => r.ok ? r.json() : []))
            );
            const shAll = [shFirstPage, ...shRestPages].flat().filter(Boolean);
            const shMap = new Map();
            for (const r of shAll) {
                if (!r?.ticker) continue;
                const latest = _latestShareholdingQuarter(r.quarterly);
                if (!latest) continue;
                shMap.set(r.ticker.trim().toUpperCase(), {
                    promoter_pct: latest.promoters != null ? Number(latest.promoters) : null,
                    fii_pct: latest.fiis != null ? Number(latest.fiis) : null,
                    dii_pct: latest.diis != null ? Number(latest.diis) : null,
                });
            }
            enriched.forEach(row => {
                const sh = shMap.get((row.ticker || "").trim().toUpperCase());
                if (sh) {
                    row.promoter_pct = sh.promoter_pct;
                    row.fii_pct = sh.fii_pct;
                    row.dii_pct = sh.dii_pct;
                }
            });
        }
    } catch (_) {
        // Leave whatever promoter_pct/fii_pct/dii_pct came from stock_ratios as a fallback.
    }

    _writeScreenerCache(enriched);
    return enriched;
}

_seedScreenerCache();

