function _prefetchScreensVcp() {
    if (_screensVcpCache.rows && _screensVcpCache.rows.length > 0 &&
        _screensVcpCache.loadedAt && (Date.now() - _screensVcpCache.loadedAt) < _SCREENS_CACHE_TTL_MS) {
        return Promise.resolve(_screensVcpCache.rows);
    }
    if (_prefetchVcpPromise) return _prefetchVcpPromise;
    _prefetchVcpPromise = (async () => {
        try {
            const rows = await _rpcScreens("get_screens_vcp");
            // returnMap kept for API-shape compatibility with any caller that
            // still reads it directly; ret_3m/6m/12m already come back joined
            // onto each row from the RPC, so this is just a ticker index.
            const returnMap = {};
            rows.forEach(r => { if (r?.ticker) returnMap[r.ticker] = { ticker: r.ticker, ret_3m: r.ret_3m, ret_6m: r.ret_6m, ret_12m: r.ret_12m }; });
            const cache = { rows, returnMap, loadedAt: Date.now() };
            _screensVcpCache = cache;
            _lsWriteScreens(_LS_SCR_VCP, cache);
            return rows;
        } catch (e) { console.warn("[prefetch] VCP failed:", e); return []; }
        finally { _prefetchVcpPromise = null; }
    })();
    return _prefetchVcpPromise;
}


async function _loadNifty500() {
    if (_nifty500Cache !== null) return _nifty500Cache;
    try {
        const headers = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` };
        const res = await fetch(`${SUPABASE_URL}/rest/v1/nifty_constituents?select=ticker&order=ticker.asc&limit=1000`, { headers });
        const rows = await res.json();
        // Supabase returns an error object (not array) when table/column is missing
        if (!Array.isArray(rows) || rows.length === 0) {
            console.warn("[Nifty500] fetch returned non-array or empty:", rows);
            return new Set(); // don't cache — allow retry on next navigation
        }
        _nifty500Cache = new Set(rows.map(r => r.ticker).filter(Boolean));
        console.log(`[Nifty500] loaded ${_nifty500Cache.size} constituents`);
    } catch (e) {
        console.warn("[Nifty500] fetch failed:", e);
        return new Set(); // don't cache — allow retry
    }
    return _nifty500Cache;
}

// Preload screener data in background right after login  so it's ready when user navigates to screener
function _preloadScreenerCache() {
    if (_screenerCache && _screenerCache.length > 0 && _isScreenerCacheFresh()) return Promise.resolve(_screenerCache);
    if (_screenerPrefetchPromise) return _screenerPrefetchPromise;
    _screenerPrefetchPromise = _fetchScreenerRows()
        .catch(() => _screenerCache || [])
        .finally(() => { _screenerPrefetchPromise = null; });
    return _screenerPrefetchPromise;
}

