function IntelligenceSignalCard({ label, value, score, T }) {
    return (
        <div style={{
            padding: "16px 18px",
            borderRadius: 16,
            border: `1px solid ${T.border}`,
            background: T.surface2,
            display: "flex",
            flexDirection: "column",
            gap: 8,
            minHeight: 120,
        }}>
            <div style={{ fontSize: 11, letterSpacing: ".12em", textTransform: "uppercase", color: T.subtext, fontWeight: 700 }}>{label}</div>
            <div style={{ fontSize: 20, fontWeight: 800, color: T.text }}>{value}</div>
            <div style={{ fontSize: 12, color: T.muted }}>Score {score.toFixed(1)} / 10</div>
        </div>
    );
}

// ─── TickerPage mini chart helpers ───────────────────────────────────────────
function TpSparkline({ data, color, fill = true, W = 200, H = 52, fmt }) {
    const [tip, setTip] = useState(null); // { x, y, val }
    const d2 = (data || []).filter(v => v != null && !isNaN(v));
    if (d2.length < 2) return <span style={{ fontSize: 12, color: "#aaa" }}>—</span>;
    const mn = Math.min(...d2), mx = Math.max(...d2), rng = mx - mn || 1;
    const pts = d2.map((v, i) => {
        const x = (i / (d2.length - 1)) * W;
        const y = H - ((v - mn) / rng) * (H - 8) - 4;
        return [x, y];
    });
    const poly = pts.map(p => p.join(",")).join(" ");
    const area = `${pts[0][0]},${H} ${poly} ${pts[pts.length - 1][0]},${H}`;
    const lp = pts[pts.length - 1];
    const fmtVal = v => fmt ? fmt(v) : (Number.isInteger(v) ? v.toLocaleString("en-IN") : v.toFixed(2));
    const handleMove = (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const mx2 = e.clientX - rect.left;
        const idx = Math.min(d2.length - 1, Math.max(0, Math.round((mx2 / rect.width) * (d2.length - 1))));
        setTip({ x: (idx / (d2.length - 1)) * 100, y: ((pts[idx][1]) / H) * 100, val: fmtVal(d2[idx]), idx });
    };
    return (
        <div style={{ position: "relative", width: "100%" }}
            onMouseMove={handleMove} onMouseLeave={() => setTip(null)}>
            <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{ display: "block" }}>
                {fill && <polygon points={area} fill={color} opacity="0.13" />}
                <polyline points={poly} fill="none" stroke={color} strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
                {tip && <circle cx={pts[tip.idx][0]} cy={pts[tip.idx][1]} r="4" fill={color} stroke="#fff" strokeWidth="1.5" />}
                <circle cx={lp[0]} cy={lp[1]} r="3" fill={color} />
            </svg>
            {tip && (
                <div style={{
                    position: "absolute", top: `${tip.y}%`, left: `${tip.x}%`,
                    transform: "translate(-50%, -130%)", pointerEvents: "none",
                    background: "rgba(10,20,35,0.88)", color: "#fff",
                    padding: "3px 8px", borderRadius: 5, fontSize: 11, fontWeight: 600,
                    whiteSpace: "nowrap", border: `1px solid ${color}`, zIndex: 10,
                }}>{tip.val}</div>
            )}
        </div>
    );
}
function TpMiniBar({ data, color, W = 280, H = 60, fmt }) {
    const [tip, setTip] = useState(null);
    const d2 = (data || []).filter(v => v != null && !isNaN(v));
    if (!d2.length) return <span style={{ fontSize: 12, color: "#aaa" }}>—</span>;
    const mx = Math.max(...d2) || 1;
    const bw = W / d2.length - 2;
    const fmtVal = v => fmt ? fmt(v) : (v >= 1000 ? `₹${(v / 100).toFixed(0)}Cr` : v.toFixed(1));
    const handleMove = (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const idx = Math.min(d2.length - 1, Math.max(0, Math.floor((e.clientX - rect.left) / rect.width * d2.length)));
        setTip({ x: ((idx + 0.5) / d2.length) * 100, val: fmtVal(d2[idx]) });
    };
    return (
        <div style={{ position: "relative", width: "100%" }}
            onMouseMove={handleMove} onMouseLeave={() => setTip(null)}>
            <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{ display: "block" }}>
                {d2.map((v, i) => {
                    const bh = (v / mx) * (H - 4);
                    return <rect key={i} x={i * (W / d2.length) + 1} y={H - bh} width={bw} height={bh} fill={color} rx="2" opacity={tip?.idx === i ? 1 : 0.82} />;
                })}
            </svg>
            {tip && (
                <div style={{
                    position: "absolute", top: "10%", left: `${tip.x}%`,
                    transform: "translateX(-50%)", pointerEvents: "none",
                    background: "rgba(10,20,35,0.88)", color: "#fff",
                    padding: "3px 8px", borderRadius: 5, fontSize: 11, fontWeight: 600,
                    whiteSpace: "nowrap", border: `1px solid ${color}`, zIndex: 10,
                }}>{tip.val}</div>
            )}
        </div>
    );
}
function TpCombo({ bars, line, bc, lc, W = 280, H = 70, fmtBar, fmtLine }) {
    const [tip, setTip] = useState(null);
    const b2 = (bars || []).map(v => v ?? 0);
    const l2 = (line || []).filter(v => v != null);
    if (!b2.length || !l2.length) return <span style={{ fontSize: 12, color: "#aaa" }}>—</span>;
    const bmx = Math.max(...b2.map(Math.abs)) || 1;
    const lmn = Math.min(...l2), lmx = Math.max(...l2), lrng = lmx - lmn || 1;
    const n = b2.length;
    const bw = (W / n) - 2;
    const toLineY = v => H - ((v - lmn) / lrng) * (H - 8) - 4;
    const linePts = l2.map((v, i) => `${(i / Math.max(n - 1, 1)) * W},${toLineY(v)}`).join(" ");
    const fmtB = v => fmtBar ? fmtBar(v) : v.toFixed(2);
    const fmtL = v => fmtLine ? fmtLine(v) : v.toFixed(2);
    const handleMove = (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const idx = Math.min(n - 1, Math.max(0, Math.floor((e.clientX - rect.left) / rect.width * n)));
        setTip({ x: ((idx + 0.5) / n) * 100, bar: fmtB(b2[idx]), line: l2[idx] != null ? fmtL(l2[idx]) : null });
    };
    return (
        <div style={{ position: "relative", width: "100%" }}
            onMouseMove={handleMove} onMouseLeave={() => setTip(null)}>
            <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{ display: "block" }}>
                {b2.map((v, i) => {
                    const bh = (Math.abs(v) / bmx) * (H - 4);
                    const isNeg = v < 0;
                    return <rect key={i} x={i * (W / n) + 1} y={isNeg ? H / 2 : H - bh} width={bw} height={bh} fill={bc} rx="2" opacity="0.72" />;
                })}
                <polyline points={linePts} fill="none" stroke={lc} strokeWidth="2" strokeLinejoin="round" />
            </svg>
            {tip && (
                <div style={{
                    position: "absolute", top: "8%", left: `${tip.x}%`,
                    transform: "translateX(-50%)", pointerEvents: "none",
                    background: "rgba(10,20,35,0.88)", color: "#fff",
                    padding: "4px 8px", borderRadius: 5, fontSize: 11, fontWeight: 600,
                    whiteSpace: "nowrap", border: `1px solid ${lc}`, zIndex: 10, lineHeight: 1.6,
                }}>
                    <span style={{ color: bc }}>■</span> {tip.bar}
                    {tip.line && <><br /><span style={{ color: lc }}>●</span> {tip.line}</>}
                </div>
            )}
        </div>
    );
}
function TpDual({ s1, s2, c1, c2, W = 280, H = 70, fmt1, fmt2 }) {
    const [tip, setTip] = useState(null);
    const a1 = (s1 || []).filter(v => v != null);
    const a2 = (s2 || []).filter(v => v != null);
    if (a1.length < 2 || a2.length < 2) return <span style={{ fontSize: 12, color: "#aaa" }}>—</span>;
    const all = [...a1, ...a2];
    const mn = Math.min(...all), mx = Math.max(...all), rng = mx - mn || 1;
    const toY = v => H - ((v - mn) / rng) * (H - 8) - 4;
    const line = (arr, c) => {
        const pts = arr.map((v, i) => `${(i / (arr.length - 1)) * W},${toY(v)}`).join(" ");
        return <polyline key={c} points={pts} fill="none" stroke={c} strokeWidth="1.8" strokeLinejoin="round" />;
    };
    const fmtV1 = v => fmt1 ? fmt1(v) : v.toFixed(2);
    const fmtV2 = v => fmt2 ? fmt2(v) : v.toFixed(2);
    const handleMove = (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const pct2 = (e.clientX - rect.left) / rect.width;
        const i1 = Math.min(a1.length - 1, Math.max(0, Math.round(pct2 * (a1.length - 1))));
        const i2 = Math.min(a2.length - 1, Math.max(0, Math.round(pct2 * (a2.length - 1))));
        setTip({ x: pct2 * 100, v1: fmtV1(a1[i1]), v2: fmtV2(a2[i2]) });
    };
    return (
        <div style={{ position: "relative", width: "100%" }}
            onMouseMove={handleMove} onMouseLeave={() => setTip(null)}>
            <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{ display: "block" }}>
                {line(a1, c1)}{line(a2, c2)}
            </svg>
            {tip && (
                <div style={{
                    position: "absolute", top: "8%", left: `${Math.min(tip.x, 75)}%`,
                    transform: "translateX(-50%)", pointerEvents: "none",
                    background: "rgba(10,20,35,0.88)", color: "#fff",
                    padding: "4px 8px", borderRadius: 5, fontSize: 11, fontWeight: 600,
                    whiteSpace: "nowrap", border: `1px solid ${c1}`, zIndex: 10, lineHeight: 1.6,
                }}>
                    <span style={{ color: c1 }}>●</span> {tip.v1}<br />
                    <span style={{ color: c2 }}>●</span> {tip.v2}
                </div>
            )}
        </div>
    );
}

// ─── Gauge Arc ────────────────────────────────────────────────────────────────
function TpGauge({ value = 7, max = 10, color = "#00e5a0", size = 88 }) {
    const r = 33, cx = size / 2, cy = size / 2;
    const toRad = d => (d * Math.PI) / 180;
    const startA = -215, endA = 35, span = endA - startA;
    const pct = Math.min(value / max, 1);
    const pt = a => ({ x: cx + r * Math.cos(toRad(a)), y: cy + r * Math.sin(toRad(a)) });
    const s = pt(startA), e = pt(startA + span * pct), te = pt(endA);
    const lg = span * pct > 180 ? 1 : 0;
    return (
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
            <path d={`M ${s.x} ${s.y} A ${r} ${r} 0 1 1 ${te.x} ${te.y}`} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="5.5" strokeLinecap="round" />
            <path d={`M ${s.x} ${s.y} A ${r} ${r} 0 ${lg} 1 ${e.x} ${e.y}`} fill="none" stroke={color} strokeWidth="5.5" strokeLinecap="round" />
            <text x={cx} y={cy + 5} textAnchor="middle" fill={color} fontSize="15" fontWeight="700" fontFamily="'IBM Plex Mono',monospace">{value}</text>
            <text x={cx} y={cy + 17} textAnchor="middle" fill="rgba(255,255,255,0.35)" fontSize="7" fontFamily="'IBM Plex Sans',sans-serif">/ {max}</text>
        </svg>
    );
}

