                                    <TpValRow label="Financial Leverage" value={raw?.fin_leverage != null ? `${Number(raw.fin_leverage).toFixed(2)}x` : raw?.debt_eq != null ? `${Number(raw.debt_eq).toFixed(2)}x` : "—"} color={C.rose} T={T} />
