//  MARKET BREADTH 

function MiniLineChart({ data, color, height = 48 }) {
    if (!data || data.length < 2) return null;
    const vals = data.map(d => d.value);
    const min = Math.min(...vals), max = Math.max(...vals);
    const range = max - min || 1;
    const w = 200, h = height;
    const pts = vals.map((v, i) => {
        const x = (i / (vals.length - 1)) * w;
        const y = h - ((v - min) / range) * (h - 4) - 2;
        return `${x},${y}`;
    }).join(" ");
    const areaBot = `${pts} ${w},${h} 0,${h}`;
    return (
        <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" style={{ width: "100%", height }}>
            <defs>
                <linearGradient id={`grad-${color.replace("#", "")}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={color} stopOpacity="0.25" />
                    <stop offset="100%" stopColor={color} stopOpacity="0" />
                </linearGradient>
            </defs>
            <polygon points={areaBot} fill={`url(#grad-${color.replace("#", "")})`} />
            <polyline points={pts} fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
    );
}


// 
//  BREADTH LINE CHART  institutional-grade, chart-first design
// 
function BreadthLineChart({ data, lines, title, T, compact = false }) {
    const [hovIdx, setHovIdx] = useState(null);
    const isDark = T.bg !== THEMES.light.bg;
    const sans = "'IBM Plex Sans', system-ui, sans-serif";
    const mono = "'IBM Plex Mono', monospace";

    if (!data || data.length === 0) return (
        <div style={{
            display: "flex", alignItems: "center", justifyContent: "center",
            height: compact ? 140 : 180, color: T.muted, fontSize: 12, fontFamily: sans
        }}>
            <div style={{ textAlign: "center", opacity: .4 }}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5"
                    style={{ marginBottom: 6, display: "block", margin: "0 auto 6px" }}>
                    <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
                </svg>
                No data
            </div>
        </div>
    );

    const allVals = lines.flatMap(l => data.map(d => d[l.key] ?? 0));
    const rawMin = Math.min(...allVals);
    const rawMax = Math.max(...allVals);
    const min = Math.max(0, Math.floor(rawMin / 10) * 10);
    const max = Math.min(100, Math.ceil(rawMax / 10) * 10);
    const range = max - min || 1;

    const H_chart = compact ? 140 : 180;
    const W = 800, PAD_L = 36, PAD_R = 12, PAD_T = 8, PAD_B = 24;
    const cW = W - PAD_L - PAD_R, cH = H_chart - PAD_T - PAD_B;

    const xOf = i => PAD_L + (i / Math.max(data.length - 1, 1)) * cW;
    const yOf = v => PAD_T + cH - ((v - min) / range) * cH;

    const yTicks = [0, 25, 50, 75, 100].filter(v => v >= min && v <= max);
    const xTickIdxs = [];
    const step = Math.max(1, Math.floor(data.length / 4));
    for (let i = 0; i < data.length; i += step) xTickIdxs.push(i);
    if (!xTickIdxs.includes(data.length - 1)) xTickIdxs.push(data.length - 1);

    const hovData = hovIdx !== null ? data[hovIdx] : null;
    const _blcLv = data.length > 0 && lines[0] ? data[data.length - 1][lines[0].key] : null;
    const _blcPv = data.length > 10 && lines[0] ? data[data.length - 11][lines[0].key] : null;
    const latestVal = (_blcLv != null && !isNaN(Number(_blcLv))) ? Number(_blcLv) : null;
    const prevVal = (_blcPv != null && !isNaN(Number(_blcPv))) ? Number(_blcPv) : null;
    const trend = latestVal != null && prevVal != null ? latestVal - prevVal : null;

    // Signal color  muted, not screaming
    const signalColor = latestVal == null ? T.subtext
        : latestVal >= 60 ? (isDark ? "#4ade80" : "#16a34a")
            : latestVal <= 40 ? T.neg
                : T.subtext;

    return (
        <div style={{ position: "relative" }}>
            {/* Single-line chart header: value + trend + legend inline */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
                {lines.length === 1 && latestVal !== null ? (
                    <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                        <span style={{
                            fontFamily: mono, fontSize: 20, fontWeight: 700,
                            color: signalColor, letterSpacing: "-.02em", lineHeight: 1
                        }}>
                            {Number(latestVal).toFixed(1)}%
                        </span>
                        {trend !== null && (
                            <span style={{
                                fontFamily: mono, fontSize: 11,
                                color: trend > 0 ? (isDark ? "#4ade80" : "#16a34a") : trend < 0 ? T.neg : T.muted,
                                fontWeight: 600
                            }}>
                                {trend > 0 ? "" : trend < 0 ? "" : ""}{Math.abs(trend).toFixed(1)}
                            </span>
                        )}
                        <span style={{ fontSize: 10, color: T.muted, fontFamily: sans }}>
                            {latestVal >= 60 ? "Bullish" : latestVal <= 40 ? "Bearish" : "Neutral"}
                        </span>
                    </div>
                ) : (
                    <div /> /* spacer for multi-line */
                )}
                {/* Legend  right aligned, compact */}
                {lines.length > 1 && (
                    <div style={{ display: "flex", gap: 14, flexWrap: "wrap" }}>
                        {lines.map(l => (
                            <div key={l.key} style={{ display: "flex", alignItems: "center", gap: 5 }}>
                                <div style={{ width: 18, height: 1.5, background: l.color, borderRadius: 2, opacity: .9 }} />
                                <span style={{ fontSize: 10, color: T.muted, fontFamily: sans, fontWeight: 500 }}>{l.label}</span>
                                {hovData && (
                                    <span style={{ fontSize: 10, color: T.text, fontFamily: mono, fontWeight: 700 }}>
                                        {(hovData[l.key] != null && !isNaN(Number(hovData[l.key])) ? Number(hovData[l.key]).toFixed(1) : "-")}%
                                    </span>
                                )}
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* SVG chart */}
            <div style={{ position: "relative", userSelect: "none" }}>
                <svg viewBox={`0 0 ${W} ${H_chart}`}
                    style={{ width: "100%", height: H_chart, display: "block", overflow: "visible" }}
                    onMouseMove={e => {
                        const rect = e.currentTarget.getBoundingClientRect();
                        const px = (e.clientX - rect.left) / rect.width * W;
                        const idx = Math.round((px - PAD_L) / cW * (data.length - 1));
                        setHovIdx(Math.max(0, Math.min(data.length - 1, idx)));
                    }}
                    onMouseLeave={() => setHovIdx(null)}>
                    <defs>
                        {lines.map(l => (
                            <linearGradient key={`g-${l.key}`} id={`g-${l.key}`} x1="0" y1="0" x2="0" y2="1">
                                <stop offset="0%" stopColor={l.color} stopOpacity={isDark ? "0.14" : "0.10"} />
                                <stop offset="100%" stopColor={l.color} stopOpacity="0" />
                            </linearGradient>
                        ))}
                        <clipPath id={`clip-${lines.map(l => l.key).join('-')}`}>
                            <rect x={PAD_L} y={PAD_T} width={cW} height={cH} />
                        </clipPath>
                    </defs>

                    {/* Y grid  very subtle */}
                    {yTicks.map(v => (
                        <g key={v}>
                            <line x1={PAD_L} y1={yOf(v)} x2={W - PAD_R} y2={yOf(v)}
                                stroke={v === 50 ? T.subtext : T.border}
                                strokeWidth={v === 50 ? "0.8" : "0.4"}
                                strokeDasharray={v === 50 ? "4,4" : "2,5"}
                                opacity={v === 50 ? "0.5" : "0.6"} />
                            <text x={PAD_L - 6} y={yOf(v) + 3.5} textAnchor="end"
                                fontSize="8.5" fill={T.muted} fontFamily={mono}>{v}</text>
                        </g>
                    ))}

                    {/* 50% label on right edge */}
                    {min <= 50 && max >= 50 && (
                        <text x={W - PAD_R + 3} y={yOf(50) + 3.5} textAnchor="start"
                            fontSize="8" fill={T.muted} fontFamily={mono}>50</text>
                    )}

                    {/* X labels */}
                    {xTickIdxs.map(i => (
                        <text key={i} x={xOf(i)} y={H_chart - 3} textAnchor="middle"
                            fontSize="8.5" fill={T.muted} fontFamily={mono}>
                            {data[i].date?.slice(2, 10)}
                        </text>
                    ))}

                    {/* Lines + area fills */}
                    {lines.map(l => {
                        const pts = data.map((d, i) => `${xOf(i).toFixed(2)},${yOf(d[l.key] ?? 0).toFixed(2)}`).join(" ");
                        const bot = PAD_T + cH;
                        const areaPts = `${pts} ${xOf(data.length - 1).toFixed(2)},${bot.toFixed(2)} ${xOf(0).toFixed(2)},${bot.toFixed(2)}`;
                        return (
                            <g key={l.key} clipPath={`url(#clip-${lines.map(l => l.key).join('-')})`}>
                                {/* Subtle area fill only for single-line charts */}
                                {lines.length === 1 && (
                                    <polygon points={areaPts} fill={`url(#g-${l.key})`} />
                                )}
                                <polyline points={pts} fill="none"
                                    stroke={l.color} strokeWidth="1.5"
                                    strokeLinecap="round" strokeLinejoin="round" />
                            </g>
                        );
                    })}

                    {/* Hover crosshair */}
                    {hovIdx !== null && (
                        <>
                            <line x1={xOf(hovIdx)} y1={PAD_T} x2={xOf(hovIdx)} y2={PAD_T + cH}
                                stroke={T.subtext} strokeWidth="0.8" strokeDasharray="3,3" opacity="0.5" />
                            {lines.map(l => (
                                <circle key={l.key}
                                    cx={xOf(hovIdx)} cy={yOf(data[hovIdx][l.key] ?? 0)}
                                    r="3" fill={l.color} stroke={T.surface} strokeWidth="1.5" />
                            ))}
                        </>
                    )}
                </svg>

                {/* Minimal tooltip */}
                {hovData && (() => {
                    const pct = hovIdx / (data.length - 1);
                    const leftAlign = pct < 0.6;
                    return (
                        <div style={{
                            position: "absolute", top: 4,
                            left: leftAlign ? `calc(${(xOf(hovIdx) / W * 100).toFixed(1)}% + 12px)` : undefined,
                            right: !leftAlign ? `calc(${((W - xOf(hovIdx)) / W * 100).toFixed(1)}% + 12px)` : undefined,
                            background: isDark ? "rgba(15,20,32,0.96)" : "rgba(255,255,255,0.97)",
                            border: `1px solid ${T.border}`,
                            borderRadius: 6, padding: "8px 12px",
                            fontSize: 11, pointerEvents: "none", zIndex: 30,
                            boxShadow: isDark ? "0 4px 20px rgba(0,0,0,0.5)" : "0 4px 16px rgba(0,0,0,0.1)",
                            minWidth: 120,
                        }}>
                            <div style={{
                                fontFamily: mono, fontSize: 9, color: T.muted,
                                marginBottom: 5, letterSpacing: ".06em", textTransform: "uppercase"
                            }}>
                                {hovData.date}
                            </div>
                            {lines.map(l => (
                                <div key={l.key} style={{
                                    display: "flex", justifyContent: "space-between",
                                    alignItems: "center", gap: 14, marginBottom: 2
                                }}>
                                    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                                        <div style={{
                                            width: 6, height: 6, borderRadius: "50%",
                                            background: l.color, flexShrink: 0
                                        }} />
                                        <span style={{ color: T.subtext, fontSize: 10 }}>{l.label}</span>
                                    </div>
                                    <span style={{
                                        fontFamily: mono, fontSize: 11, fontWeight: 700,
                                        color: T.text
                                    }}>{(hovData[l.key] != null && !isNaN(Number(hovData[l.key])) ? Number(hovData[l.key]).toFixed(1) : "-")}%</span>
                                </div>
                            ))}
                        </div>
                    );
                })()}
            </div>
        </div>
    );
}

// 
//  MARKET BREADTH MODULE  institutional-grade redesign
// 
/* ============================================================================
 * REVISED: MarketBreadthModule
 * ----------------------------------------------------------------------------
 * What changed vs. the original:
 *   The "screens" section (Top 52W High Proximity, Top RS 3M/6M/12M,
 *   RS Rating, RS Acceleration, Trend Aligned) previously paginated through
 *   6 tables client-side (indicators x3, stock_prices_daily, stock_returns,
 *   stock_52w, company_financials  up to ~30-40 requests) and joined/sorted
 *   the full ~1,500-2,000 stock universe in JS, even though only the top 50
 *   rows of each list are ever rendered.
 *
 *   That's now a single call to the get_breadth_screens() Postgres RPC
 *   (see market_breadth_screens_migration.sql), which does the joins,
 *   filtering and ranking server-side and returns only the top ~300 rows
 *   per list (buffer for the client-side Nifty-500 filter).
 *
 *   The chart time-series fetch (market_breadth table) is untouched  it
 *   was already a single lightweight query with no joins.
 *
 * Drop-in: replace the existing MarketBreadthModule function in App.jsx
 * with this one. No other files need to change except the small
 * _breadthCache seed object near the top of App.jsx (optional cleanup 
 * see note below); the existing shape still works fine as-is since JS
 * objects don't require pre-declared keys.
 * ============================================================================ */
function MarketBreadthModule({ T, onDataReady }) {
    const exchange = "NSE";
    const [range, setRange] = useState("1Y");
    // If the module-level cache was already seeded from localStorage, start non-loading
    // and pre-populate all state so the header renders on the very first paint.
    const _hasSeededCache = !!(
        _breadthCache.data && _breadthCache.data.length > 0 &&
        _breadthCache.range && _breadthCache.top52wHigh && _breadthCache.topRS &&
        _breadthCache.nameMap && _breadthCache.trendAligned &&
        _breadthCache.rsRating && _breadthCache.rsAcceleration
    );
    const [data, setData] = useState(() => _hasSeededCache ? _breadthCache.data : []);
    const [top52wHigh, setTop52wHigh] = useState(() => _hasSeededCache ? _breadthCache.top52wHigh : []);
    const [topRS, setTopRS] = useState(() => _hasSeededCache ? _breadthCache.topRS : { rs3m: [], rs6m: [], rs12m: [] });
    const [trendAligned, setTrendAligned] = useState(() => _hasSeededCache ? _breadthCache.trendAligned : []);
    const [rsRating, setRsRating] = useState(() => _hasSeededCache ? _breadthCache.rsRating : []);
    const [rsAcceleration, setRsAcceleration] = useState(() => _hasSeededCache ? _breadthCache.rsAcceleration : []);
    const [nameMap, setNameMap] = useState(() => _hasSeededCache ? (_breadthCache.nameMap || {}) : {});
    const [industryMap, setIndustryMap] = useState(() => _hasSeededCache ? (_breadthCache.industryMap || {}) : {});
    const [loading, setLoading] = useState(!_hasSeededCache);
    const [refreshing, setRefreshing] = useState(false); // SWR: background refresh indicator
    const [tablesLoading, setTablesLoading] = useState(!_hasSeededCache);
    const [refreshTick, setRefreshTick] = useState(0); // bump to force useEffect re-run
    const H = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}`, "Cache-Control": "max-age=300" };

    const isDark = T.bg !== THEMES.light.bg;
    const sans = "'IBM Plex Sans', system-ui, sans-serif";
    const mono = "'IBM Plex Mono', monospace";

    const rangeDate = () => {
        const d = new Date();
        if (range === "3M") d.setMonth(d.getMonth() - 3);
        else if (range === "6M") d.setMonth(d.getMonth() - 6);
        else if (range === "1Y") d.setFullYear(d.getFullYear() - 1);
        else if (range === "2Y") d.setFullYear(d.getFullYear() - 2);
        else if (range === "3Y") d.setFullYear(d.getFullYear() - 3);
        else if (range === "5Y") d.setFullYear(d.getFullYear() - 5);
        return d.toISOString().split("T")[0];
    };

    // ------------------------------------------------------------------
    // Screens data (Top 52W High Proximity / Top RS / RS Rating / RS
    // Acceleration / Trend Aligned) now come from a single server-side
    // RPC — get_breadth_screens() — instead of the client paginating
    // through indicators (x3), stock_prices_daily, stock_returns,
    // stock_52w, and company_financials and joining/sorting the full
    // NSE universe in JS. See market_breadth_screens_migration.sql.
    // ------------------------------------------------------------------

    useEffect(() => {
        const abortCtrl = new AbortController();
        const sig = abortCtrl.signal;
        const load = async () => {
            const _cacheAge = _breadthCache.loadedAt ? Date.now() - _breadthCache.loadedAt : Infinity;
            const hasStale = !!(
                _breadthCache.data && _breadthCache.data.length > 0 &&
                _breadthCache.range === range &&
                _breadthCache.top52wHigh && _breadthCache.topRS && _breadthCache.nameMap &&
                _breadthCache.trendAligned && _breadthCache.rsRating && _breadthCache.rsAcceleration
            );

            //  STEP 1: serve stale instantly  no loading spinner 
            if (hasStale) {
                setData(_breadthCache.data);
                setTop52wHigh(_breadthCache.top52wHigh);
                setTopRS(_breadthCache.topRS);
                setNameMap(_breadthCache.nameMap);
                if (_breadthCache.industryMap) setIndustryMap(_breadthCache.industryMap);
                setTrendAligned(_breadthCache.trendAligned);
                setRsRating(_breadthCache.rsRating);
                setRsAcceleration(_breadthCache.rsAcceleration);
                setLoading(false); setTablesLoading(false);
                if (onDataReady) onDataReady({
                    top52wHigh: _breadthCache.top52wHigh,
                    topRS: _breadthCache.topRS,
                    trendAligned: _breadthCache.trendAligned,
                    rsRating: _breadthCache.rsRating,
                    rsAcceleration: _breadthCache.rsAcceleration,
                    nameMap: _breadthCache.nameMap,
                    industryMap: _breadthCache.industryMap || {},
                    tablesLoading: false,
                });

                // Fresh enough  skip network entirely
                if (_cacheAge < _BREADTH_CACHE_TTL_MS) return;

                // Stale  revalidate silently
                setRefreshing(true);
            } else {
                // No cache at all  show spinner
                setLoading(true);
                setTablesLoading(true);
            }
            try {
                const from = rangeDate();

                //  1) Chart time series  single table, already lightweight, unchanged 
                const breadthRows = await fetch(
                    `${SUPABASE_URL}/rest/v1/market_breadth?exchange=eq.${exchange}&date=gte.${from}&order=date.asc&limit=2000`,
                    { headers: H, signal: sig }
                ).then(r => r.json()).catch(() => []);

                // Detect Supabase error response (returns {message, code, hint, details} instead of array)
                const isBreadthError = !Array.isArray(breadthRows) || breadthRows?.code || breadthRows?.message;
                const cleanData = (!isBreadthError && Array.isArray(breadthRows)) ? breadthRows.filter(r =>
                    r != null &&
                    r.above_sma20 != null && r.above_sma50 != null &&
                    r.above_sma150 != null && r.above_sma200 != null
                ) : null; // null = fetch failed/error, don't overwrite stale

                if (cleanData !== null) {
                    // Valid response  update cache and state
                    _breadthCache.data = cleanData;
                    _breadthCache.range = range;
                    setData(cleanData);
                } else if (!hasStale) {
                    // Failed fetch AND no stale data to fall back on  show empty state
                    console.warn("[Breadth] Fetch returned error or non-array:", breadthRows);
                    setData([]);
                } else {
                    // Failed fetch but stale data is showing  keep it, log the error
                    console.warn("[Breadth] Background refresh failed, keeping stale data:", breadthRows);
                }
                setLoading(false);

                //  2) Screens  a single server-side RPC does the joins, filtering,
                //     ranking and sorting inside Postgres and returns only the top
                //     p_limit rows per list (default 300  a buffer for the client
                //     -side Nifty-500 filter, since the UI only ever shows 50).
                const screensRes = await fetch(`${SUPABASE_URL}/rest/v1/rpc/get_breadth_screens`, {
                    method: "POST",
                    headers: { ...H, "Content-Type": "application/json" },
                    signal: sig,
                    body: JSON.stringify({ p_exchange: exchange, p_min_market_cap: 500, p_limit: 300 }),
                }).then(r => r.json()).catch(e => ({ __error: e.message }));

                const screensFailed = !screensRes || screensRes.__error || screensRes.code || screensRes.message;
                if (screensFailed) {
                    if (!hasStale) console.warn("[Breadth] get_breadth_screens RPC failed:", screensRes);
                    else console.warn("[Breadth] Background screens refresh failed, keeping stale data:", screensRes);
                    setTablesLoading(false);
                    setRefreshing(false);
                    return;
                }

                const {
                    latestDate,
                    top52wHigh: top52wHighRows = [],
                    topRS: topRSRows = { rs3m: [], rs6m: [], rs12m: [] },
                    rsRating: rsRatingRows = [],
                    rsAcceleration: rsAccelerationRows = [],
                    trendAligned: trendAlignedRows = [],
                } = screensRes;

                // Build ticker  name/industry maps from whatever rows came back.
                // Cheap now: each list is capped at p_limit rows (not the full
                // ~1,500-2,000 stock universe), so this is a tiny dedup pass.
                const nameMapInit = {};
                const industryMap = {};
                const allScreenRows = [
                    ...top52wHighRows,
                    ...topRSRows.rs3m, ...topRSRows.rs6m, ...topRSRows.rs12m,
                    ...rsRatingRows, ...rsAccelerationRows, ...trendAlignedRows,
                ];
                allScreenRows.forEach(r => {
                    if (!r?.ticker) return;
                    if (r.name) nameMapInit[r.ticker] = r.name;
                    if (r.industry) industryMap[r.ticker] = r.industry;
                });

                setNameMap(nameMapInit);
                setIndustryMap(industryMap);
                setTop52wHigh(top52wHighRows);
                setTopRS(topRSRows);
                setRsRating(rsRatingRows);
                setRsAcceleration(rsAccelerationRows);
                setTrendAligned(trendAlignedRows);

                _breadthCache.nameMap = nameMapInit;
                _breadthCache.industryMap = industryMap;
                _breadthCache.latestDate = latestDate;
                _breadthCache.top52wHigh = top52wHighRows;
                _breadthCache.topRS = topRSRows?.rs3m?.length ? topRSRows : null;
                _breadthCache.rsRating = rsRatingRows;
                _breadthCache.rsAcceleration = rsAccelerationRows;
                _breadthCache.trendAligned = trendAlignedRows;
                _breadthCache.loadedAt = Date.now();

                // Only persist to localStorage when we actually have data  never write empty cache
                if (_breadthCache.data && _breadthCache.data.length > 0) {
                    _lsWrite(_LS_BREADTH_KEY, {
                        data: _breadthCache.data,
                        range: _breadthCache.range,
                        top52wHigh: top52wHighRows,
                        topRS: _breadthCache.topRS,
                        rsRating: rsRatingRows,
                        rsAcceleration: rsAccelerationRows,
                        trendAligned: trendAlignedRows,
                        nameMap: nameMapInit,
                        industryMap: industryMap,
                        loadedAt: _breadthCache.loadedAt,
                    });
                }

                if (onDataReady) onDataReady({
                    top52wHigh: top52wHighRows,
                    topRS: topRSRows,
                    trendAligned: trendAlignedRows,
                    rsRating: rsRatingRows,
                    rsAcceleration: rsAccelerationRows,
                    nameMap: nameMapInit,
                    industryMap: industryMap,
                    tablesLoading: false,
                });
            } catch (e) {
                if (e.name !== "AbortError") {
                    if (!hasStale) console.error(e); // full error only if nothing shown
                    else console.warn("[Breadth] Background refresh failed:", e.message);
                }
            }
            setLoading(false);
            setTablesLoading(false);
            setRefreshing(false);
        };
        load();
        return () => abortCtrl.abort();
    }, [exchange, range, refreshTick]);


    //  Chart configs 
    // Single consistent color per indicator  no rainbow
    const CHART_CONFIGS = [
        { id: "sma20", title: "% Above SMA-20", allKey: "above_sma20", allColor: isDark ? "#6366f1" : "#4f46e5", capPrefix: "sma20" },
        { id: "sma50", title: "% Above SMA-50", allKey: "above_sma50", allColor: isDark ? "#6366f1" : "#4f46e5", capPrefix: "sma50" },
        { id: "sma150", title: "% Above SMA-150", allKey: "above_sma150", allColor: isDark ? "#6366f1" : "#4f46e5", capPrefix: "sma150" },
        { id: "sma200", title: "% Above SMA-200", allKey: "above_sma200", allColor: isDark ? "#6366f1" : "#4f46e5", capPrefix: "sma200" },
        { id: "52high", title: "% Near 52W High", allKey: "near_52w_high", allColor: isDark ? "#4ade80" : "#16a34a", capPrefix: "52high" },
        { id: "52low", title: "% Near 52W Low", allKey: "near_52w_low", allColor: isDark ? "#f87171" : "#dc2626", capPrefix: "52low" },
    ];

    const CAP_COL_MAP = {
        sma20: { large: "large_cap_above_sma20", mid: "mid_cap_above_sma20", small: "small_cap_above_sma20" },
        sma50: { large: "large_cap_above_sma50", mid: "mid_cap_above_sma50", small: "small_cap_above_sma50" },
        sma150: { large: "large_cap_above_sma150", mid: "mid_cap_above_sma150", small: "small_cap_above_sma150" },
        sma200: { large: "large_cap_above_sma200", mid: "mid_cap_above_sma200", small: "small_cap_above_sma200" },
        "52high": { large: "large_cap_near_52w_high", mid: "mid_cap_near_52w_high", small: "small_cap_near_52w_high" },
        "52low": { large: "large_cap_near_52w_low", mid: "mid_cap_near_52w_low", small: "small_cap_near_52w_low" },
    };

    const CAP_SEGMENTS = [
        { id: "all", label: "All" },
        { id: "large", label: "Large" },
        { id: "mid", label: "Mid" },
        { id: "small", label: "Small" },
    ];

    const [chartSegs, setChartSegs] = useState(() =>
        Object.fromEntries(CHART_CONFIGS.map(c => [c.id, new Set(["all"])]))
    );
    const toggleSeg = (chartId, segId) => {
        setChartSegs(prev => {
            const cur = new Set(prev[chartId]);
            if (segId === "all") {
                if (cur.size === 1 && cur.has("all")) return prev;
                return { ...prev, [chartId]: new Set(["all"]) };
            }
            cur.delete("all");
            if (cur.has(segId)) {
                cur.delete(segId);
                if (cur.size === 0) return { ...prev, [chartId]: new Set(["all"]) };
            } else {
                cur.add(segId);
            }
            return { ...prev, [chartId]: cur };
        });
    };

    const buildLines = cfg => {
        const segs = chartSegs[cfg.id];
        const lines = [];
        if (segs.has("all")) lines.push({ key: cfg.allKey, label: "All", color: cfg.allColor });
        const cols = CAP_COL_MAP[cfg.capPrefix] || {};
        // Cap breakdowns use slightly dimmer versions of the main color
        const capColor = isDark ? "#94a3b8" : "#64748b";
        if (segs.has("large") && cols.large) lines.push({ key: cols.large, label: "Large", color: isDark ? "#818cf8" : "#6366f1" });
        if (segs.has("mid") && cols.mid) lines.push({ key: cols.mid, label: "Mid", color: isDark ? "#fb923c" : "#ea580c" });
        if (segs.has("small") && cols.small) lines.push({ key: cols.small, label: "Small", color: isDark ? "#4ade80" : "#16a34a" });
        return lines;
    };

    // Latest snapshot
    const latestRow = data.length > 0 ? data[data.length - 1] : null;
    const prevRow = data.length > 1 ? data[data.length - 2] : null;
    const fiveDayRows = data.slice(-5);

    const RANGE_OPTS = ["6M", "1Y", "2Y", "3Y"];
    const shellBorder = isDark ? "rgba(120,140,170,0.16)" : "rgba(15,23,42,0.08)";
    const chartCardBg = isDark
        ? "linear-gradient(180deg, rgba(17,24,39,0.92), rgba(9,14,25,0.96))"
        : "linear-gradient(180deg, rgba(255,255,255,0.98), rgba(248,250,252,0.98))";
    const getChartTone = (value, inverse = false) => {
        if (value == null) return { label: "Neutral", color: T.subtext };
        if (inverse) {
            if (value >= 25) return { label: "Stress Elevated", color: T.neg };
            if (value >= 15) return { label: "Pressure Building", color: isDark ? "#f59e0b" : "#d97706" };
            return { label: "Stress Contained", color: T.green };
        }
        if (value >= 60) return { label: "Participation Strong", color: T.green };
        if (value >= 40) return { label: "Mixed Breadth", color: isDark ? "#f59e0b" : "#d97706" };
        return { label: "Participation Weak", color: T.neg };
    };
    const renderBreadthChartCard = (cfg, compact = false) => {
        const lines = buildLines(cfg);
        const activeSeg = chartSegs[cfg.id];
        const mainKey = lines[0]?.key;
        const _lv = mainKey && latestRow ? latestRow[mainKey] : null;
        const _pv = mainKey && prevRow ? prevRow[mainKey] : null;
        const latestVal = (_lv != null && !isNaN(Number(_lv))) ? Number(_lv) : null;
        const prevVal = (_pv != null && !isNaN(Number(_pv))) ? Number(_pv) : null;
        const deltaVal = latestVal != null && prevVal != null ? +(latestVal - prevVal).toFixed(1) : null;
        const tone = getChartTone(latestVal, cfg.id === "52low");
        const cardRadius = compact ? 22 : 26;
        const cardPadding = compact ? 16 : 18;
        const valueSize = compact ? 17 : 18;
        const pillFont = compact ? 8.5 : 9;
        const chartNote = compact ? "Mobile breadth view" : "Breadth panel";

        return (
            <div key={cfg.id} style={{
                position: "relative",
                overflow: "hidden",
                borderRadius: cardRadius,
                padding: cardPadding,
                border: `1px solid ${shellBorder}`,
                background: chartCardBg,
                boxShadow: isDark
                    ? "0 24px 56px rgba(2,6,23,0.28), inset 0 1px 0 rgba(255,255,255,0.04)"
                    : "0 20px 42px rgba(15,23,42,0.08), inset 0 1px 0 rgba(255,255,255,0.85)",
            }}>
                <div style={{
                    position: "absolute", inset: 0, pointerEvents: "none",
                    background: isDark
                        ? `radial-gradient(circle at top right, ${tone.color}18, transparent 28%)`
                        : `radial-gradient(circle at top right, ${tone.color}12, transparent 30%)`
                }} />
                <div style={{ position: "relative" }}>
                    <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: compact ? 12 : 14, flexWrap: compact ? "wrap" : "nowrap" }}>
                        <div style={{ minWidth: 0, flex: 1 }}>
                            <div style={{
                                fontSize: 10, fontWeight: 800, color: T.muted,
                                textTransform: "uppercase", letterSpacing: ".14em", marginBottom: 8
                            }}>
                                {cfg.title}
                            </div>
                            <div style={{ fontSize: compact ? 10 : 10.5, color: T.subtext, marginBottom: 8 }}>
                                {chartNote}
                            </div>
                            <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 6, flexWrap: "wrap" }}>
                                <span style={{
                                    fontFamily: mono, fontSize: valueSize, fontWeight: 800,
                                    color: tone.color, letterSpacing: "-.03em", lineHeight: 1
                                }}>
                                    {latestVal == null ? "-" : `${Number(latestVal).toFixed(1)}%`}
                                </span>
                                {deltaVal != null && (
                                    <span style={{
                                        fontFamily: mono, fontSize: 10.5, fontWeight: 700,
                                        color: deltaVal >= 0 ? T.green : T.neg
                                    }}>
                                        {deltaVal >= 0 ? "+" : ""}{deltaVal} (1D)
                                    </span>
                                )}
                            </div>
                            <span style={{
                                display: "inline-flex", alignItems: "center",
                                padding: "4px 10px", borderRadius: 999,
                                border: `1px solid ${tone.color}2a`,
                                background: `${tone.color}12`,
                                color: tone.color, fontSize: pillFont, fontWeight: 700,
                                letterSpacing: ".05em", textTransform: "uppercase"
                            }}>
                                {tone.label}
                            </span>
                        </div>
                        <div style={{
                            display: "flex", background: isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.72)",
                            borderRadius: 999, padding: 3, gap: 4, border: `1px solid ${shellBorder}`,
                            boxShadow: isDark ? "inset 0 1px 0 rgba(255,255,255,0.03)" : "inset 0 1px 0 rgba(255,255,255,0.9)",
                            width: compact ? "100%" : "auto",
                            justifyContent: compact ? "space-between" : "flex-start"
                        }}>
                            {CAP_SEGMENTS.map(seg => {
                                const active = activeSeg.has(seg.id);
                                return (
                                    <button
                                        key={seg.id}
                                        onClick={() => toggleSeg(cfg.id, seg.id)}
                                        style={{
                                            height: compact ? 26 : 24,
                                            padding: compact ? "0 11px" : "0 10px",
                                            border: "none",
                                            borderRadius: 999,
                                            background: active ? (isDark ? "rgba(255,255,255,0.12)" : "#ffffff") : "transparent",
                                            color: active ? T.text : T.muted,
                                            fontWeight: active ? 700 : 500,
                                            fontSize: compact ? 9.5 : 9,
                                            fontFamily: sans,
                                            cursor: "pointer",
                                            transition: ".15s",
                                            boxShadow: active ? `0 8px 18px ${isDark ? "rgba(2,6,23,0.22)" : "rgba(15,23,42,0.08)"}` : "none",
                                            flex: compact ? 1 : "0 0 auto"
                                        }}
                                    >
                                        {seg.label}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    <BreadthLineChart data={data} lines={lines} title="" T={T} compact={true} />
                </div>
            </div>
        );
    };

    return (
        <div style={{ flex: 1, overflowY: "auto", background: T.bg, fontFamily: sans }}>
            <div style={{ width: "100%", maxWidth: 1400, margin: "0 auto" }}>
                {refreshing && (
                    <div style={{
                        display: "flex", alignItems: "center", gap: 6, padding: "4px 24px",
                        fontSize: 11, color: T.subtext, opacity: 0.55
                    }}>
                        <span style={{
                            width: 6, height: 6, borderRadius: "50%", background: T.green,
                            display: "inline-block", animation: "pulse 1.2s ease-in-out infinite"
                        }} />
                        Refreshing data...
                    </div>
                )}

                {loading ? (
                    <div style={{
                        display: "flex", alignItems: "center", justifyContent: "center",
                        height: 400, color: T.subtext
                    }}>
                        <div style={{ textAlign: "center" }}>
                            <div style={{
                                width: 28, height: 28, border: `1.5px solid ${T.border}`,
                                borderTopColor: isDark ? "#6366f1" : "#4f46e5",
                                borderRadius: "50%", margin: "0 auto 12px",
                                animation: "finspin .8s linear infinite"
                            }} />
                            <div style={{ fontSize: 12, color: T.subtext }}>Loading...</div>
                        </div>
                    </div>
                ) : (
                    <>
                        <div className="breadth-desktop-charts" style={{ padding: "24px 24px 56px" }}>
                            <div style={{
                                position: "relative",
                                overflow: "hidden",
                                borderRadius: 30,
                                padding: 24,
                                marginBottom: 22,
                                border: `1px solid ${shellBorder}`,
                                background: isDark
                                    ? "linear-gradient(180deg, rgba(8,12,20,0.96), rgba(11,18,32,0.98))"
                                    : "linear-gradient(180deg, rgba(255,255,255,0.98), rgba(241,245,249,0.98))",
                                boxShadow: isDark
                                    ? "0 28px 70px rgba(2,6,23,0.30), inset 0 1px 0 rgba(255,255,255,0.04)"
                                    : "0 24px 60px rgba(15,23,42,0.08), inset 0 1px 0 rgba(255,255,255,0.85)"
                            }}>
                                <div style={{
                                    position: "absolute", inset: 0, pointerEvents: "none",
                                    background: isDark
                                        ? "radial-gradient(circle at top right, rgba(16,185,129,0.10), transparent 24%), radial-gradient(circle at bottom left, rgba(59,130,246,0.08), transparent 24%)"
                                        : "radial-gradient(circle at top right, rgba(16,185,129,0.09), transparent 24%), radial-gradient(circle at bottom left, rgba(59,130,246,0.07), transparent 24%)"
                                }} />

                                <div style={{ position: "relative" }}>
                                    <div style={{ display: "flex", justifyContent: "space-between", gap: 20, alignItems: "flex-end", marginBottom: 24, flexWrap: "wrap" }}>
                                        <div>
                                            <div style={{ fontSize: 10, fontWeight: 800, color: T.muted, textTransform: "uppercase", letterSpacing: ".16em", marginBottom: 10 }}>
                                                Breadth Dashboard
                                            </div>
                                            <div style={{ fontSize: 24, fontWeight: 800, color: T.text, letterSpacing: "-.03em", marginBottom: 8 }}>
                                                Market participation across trend horizons
                                            </div>

                                        </div>
                                        <div style={{ display: "flex", flexDirection: "column", gap: 12, alignItems: "flex-end" }}>
                                            <div style={{
                                                display: "flex", alignItems: "center", gap: 10, padding: "10px 14px",
                                                borderRadius: 18, border: `1px solid ${shellBorder}`,
                                                background: isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.72)"
                                            }}>
                                                <span style={{ width: 10, height: 10, borderRadius: 999, background: T.green, boxShadow: `0 0 0 6px ${T.green}18` }} />
                                                <div>
                                                    <div style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".12em", textTransform: "uppercase", color: T.muted }}>
                                                        Coverage
                                                    </div>
                                                    <div style={{ fontSize: 12, fontWeight: 700, color: T.text }}>
                                                        6 internal breadth panels
                                                    </div>
                                                </div>
                                            </div>
                                            <div style={{
                                                display: "flex",
                                                background: isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.72)",
                                                borderRadius: 999,
                                                padding: 3,
                                                gap: 4,
                                                border: `1px solid ${shellBorder}`,
                                                boxShadow: isDark ? "inset 0 1px 0 rgba(255,255,255,0.03)" : "inset 0 1px 0 rgba(255,255,255,0.9)"
                                            }}>
                                                {RANGE_OPTS.map(r => (
                                                    <button
                                                        key={r}
                                                        onClick={() => setRange(r)}
                                                        style={{
                                                            height: 28,
                                                            padding: "0 14px",
                                                            border: "none",
                                                            borderRadius: 999,
                                                            background: range === r ? (isDark ? "rgba(255,255,255,0.12)" : "#ffffff") : "transparent",
                                                            color: range === r ? T.text : T.muted,
                                                            fontWeight: range === r ? 700 : 500,
                                                            fontSize: 11,
                                                            fontFamily: sans,
                                                            cursor: "pointer",
                                                            transition: ".15s",
                                                            boxShadow: range === r ? `0 8px 18px ${isDark ? "rgba(2,6,23,0.22)" : "rgba(15,23,42,0.08)"}` : "none"
                                                        }}
                                                    >
                                                        {r}
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    </div>

                                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginBottom: 20 }}>
                                        {CHART_CONFIGS.slice(0, 4).map(cfg => renderBreadthChartCard(cfg))}
                                    </div>

                                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20 }}>
                                        {CHART_CONFIGS.slice(4, 6).map(cfg => renderBreadthChartCard(cfg))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="breadth-mobile-charts" style={{ padding: "14px 12px 32px" }}>
                            <div style={{
                                position: "relative",
                                overflow: "hidden",
                                borderRadius: 24,
                                padding: 16,
                                marginBottom: 14,
                                border: `1px solid ${shellBorder}`,
                                background: isDark
                                    ? "linear-gradient(180deg, rgba(8,12,20,0.96), rgba(11,18,32,0.98))"
                                    : "linear-gradient(180deg, rgba(255,255,255,0.98), rgba(241,245,249,0.98))",
                                boxShadow: isDark
                                    ? "0 18px 44px rgba(2,6,23,0.26), inset 0 1px 0 rgba(255,255,255,0.04)"
                                    : "0 16px 36px rgba(15,23,42,0.08), inset 0 1px 0 rgba(255,255,255,0.85)"
                            }}>
                                <div style={{
                                    position: "absolute", inset: 0, pointerEvents: "none",
                                    background: isDark
                                        ? "radial-gradient(circle at top right, rgba(16,185,129,0.10), transparent 28%), radial-gradient(circle at bottom left, rgba(59,130,246,0.08), transparent 28%)"
                                        : "radial-gradient(circle at top right, rgba(16,185,129,0.09), transparent 30%), radial-gradient(circle at bottom left, rgba(59,130,246,0.07), transparent 30%)"
                                }} />
                                <div style={{ position: "relative" }}>
                                    <div style={{ fontSize: 9, fontWeight: 800, color: T.muted, textTransform: "uppercase", letterSpacing: ".16em", marginBottom: 8 }}>
                                        Breadth Dashboard
                                    </div>
                                    <div style={{ fontSize: 20, fontWeight: 800, color: T.text, letterSpacing: "-.03em", marginBottom: 8, lineHeight: 1.1 }}>
                                        Market participation across trend horizons
                                    </div>
                                    <div style={{ fontSize: 12, lineHeight: 1.65, color: T.subtext, marginBottom: 12 }}>
                                        Swipe through a mobile-first stack of the six internal breadth panels with the same live participation signals.
                                    </div>
                                    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                                        <div style={{
                                            display: "inline-flex", alignItems: "center", gap: 8, padding: "8px 12px",
                                            borderRadius: 999, border: `1px solid ${shellBorder}`,
                                            background: isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.72)"
                                        }}>
                                            <span style={{ width: 8, height: 8, borderRadius: 999, background: T.green, boxShadow: `0 0 0 5px ${T.green}18` }} />
                                            <span style={{ fontSize: 11, fontWeight: 700, color: T.text }}>6 internal breadth panels</span>
                                        </div>
                                        <div style={{
                                            display: "flex",
                                            background: isDark ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.72)",
                                            borderRadius: 999,
                                            padding: 3,
                                            gap: 4,
                                            border: `1px solid ${shellBorder}`,
                                            boxShadow: isDark ? "inset 0 1px 0 rgba(255,255,255,0.03)" : "inset 0 1px 0 rgba(255,255,255,0.9)"
                                        }}>
                                            {RANGE_OPTS.map(r => (
                                                <button
                                                    key={r}
                                                    onClick={() => setRange(r)}
                                                    style={{
                                                        height: 32,
                                                        flex: 1,
                                                        padding: "0 12px",
                                                        border: "none",
                                                        borderRadius: 999,
                                                        background: range === r ? (isDark ? "rgba(255,255,255,0.12)" : "#ffffff") : "transparent",
                                                        color: range === r ? T.text : T.muted,
                                                        fontWeight: range === r ? 700 : 500,
                                                        fontSize: 11,
                                                        fontFamily: sans,
                                                        cursor: "pointer",
                                                        transition: ".15s",
                                                        boxShadow: range === r ? `0 8px 18px ${isDark ? "rgba(2,6,23,0.22)" : "rgba(15,23,42,0.08)"}` : "none"
                                                    }}
                                                >
                                                    {r}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                                {CHART_CONFIGS.map(cfg => renderBreadthChartCard(cfg, true))}
                            </div>
                        </div>
                    </>
                )}
            </div>
        </div>
    );

}
