function _isMarketHours() {
    const now = new Date();
    const ist = new Date(now.toLocaleString("en-US", { timeZone: "Asia/Kolkata" }));
    const h = ist.getHours(), m = ist.getMinutes(), d = ist.getDay();
    if (d === 0 || d === 6) return false;
    const mins = h * 60 + m;
    return mins >= 555 && mins <= 930; // 9:15  15:30
}
function _hmTTL() { return _isMarketHours() ? 60_000 : 10 * 60_000; }
function _lsGet(k) { try { const s = localStorage.getItem(k); return s ? JSON.parse(s) : null; } catch { return null; } }
function _lsSet(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch { } }

