export default function App() {
    const initialRoute = parseAppRoute(typeof window !== "undefined" ? window.location.pathname : "/");
    const restoringHistoryRef = useRef(false);
    const [session, setSession] = useState(null);
    const [openDropdown, setOpenDropdown] = useState(null);
    const [isDemo, setIsDemo] = useState(false);
    const [trades, setTrades] = useState([]);
    const [quotes, setQuotes] = useState({});
    const [funds, setFunds] = useState([]);
    const [dividends, setDividends] = useState([]);

    const [page, setPage] = useState(initialRoute.page || DEFAULT_APP_STATE.page);
    const [productTab, setProductTab] = useState(initialRoute.productTab || DEFAULT_APP_STATE.productTab);

    // Auto-save guest journal data to localStorage whenever it changes (only when not logged in / not demo)
    // eslint-disable-next-line react-hooks/exhaustive-deps
    const [previousState, setPreviousState] = useState(null);
    const [legalInitialTab, setLegalInitialTab] = useState(initialRoute.legalInitialTab || DEFAULT_APP_STATE.legalInitialTab);

    const openLegal = (tabId) => {
        setPreviousState({
            productTab,
            page,
            financialSubPage,
            technicalSubPage
        });
        setLegalInitialTab(tabId);
        setProductTab("disclaimer");
    };

    const closeLegal = () => {
        if (previousState) {
            setProductTab(previousState.productTab);
            setPage(previousState.page);
            setFinancialSubPage(previousState.financialSubPage);
            setTechnicalSubPage(previousState.technicalSubPage);
            setPreviousState(null);
        } else {
            setProductTab("dashboard");
            setPage("dashboard");
        }
    };

    const [route, setRoute] = useState(initialRoute);
    const [financialSubPage, setFinancialSubPage] = useState(initialRoute.financialSubPage || DEFAULT_APP_STATE.financialSubPage);
    const [technicalSubPage, setTechnicalSubPage] = useState(initialRoute.technicalSubPage || DEFAULT_APP_STATE.technicalSubPage);
    const [topbarSearch, setTopbarSearch] = useState("");
    const [topbarSuggestions, setTopbarSuggestions] = useState([]);
    const [showTopbarSuggestions, setShowTopbarSuggestions] = useState(false);
    const [activeTopbarSuggIdx, setActiveTopbarSuggIdx] = useState(-1);
    const [topbarSearchRequest, setTopbarSearchRequest] = useState(null);
    const [technoFundaFilter, setTechnoFundaFilter] = useState(null); // { label, tickers: Set }
    const [technoFundaSource, setTechnoFundaSource] = useState(null); // "watchlist" | "screens" | null
    const topbarSearchTimerRef = useRef(null);
    const topbarSearchWrapRef = useRef(null);
    const topbarSearchDropdownRef = useRef(null);
    const topbarResolvedSymRef = useRef(null);

    const syncRoute = useCallback((path, replace = false) => {
        const nextRoute = parseAppRoute(path);
        if (typeof window !== "undefined") {
            if (replace) window.history.replaceState(null, "", path);
            else window.history.pushState(null, "", path);
        }
        setRoute(nextRoute);
    }, []);

    const clearTickerRoute = useCallback(() => {
        if (typeof window === "undefined") return;
        if (!window.location.pathname.startsWith("/ticker/")) return;
        setRoute({ kind: "app", productTab, page, financialSubPage, technicalSubPage, legalInitialTab });
        setTopbarSearch("");
        topbarResolvedSymRef.current = null;
    }, [productTab, page, financialSubPage, technicalSubPage, legalInitialTab]);

    const navigateToTicker = useCallback((rawSymbol, options = {}) => {
        const symbol = (rawSymbol || "").trim().toUpperCase();
        if (!symbol) return;
        setProductTab("financial");
        setFinancialSubPage("search");
        setTechnoFundaFilter(null);
        setTechnoFundaSource(null);
        setOpenDropdown(null);
        setTopbarSearch(symbol);
        topbarResolvedSymRef.current = symbol;
        // Replace history if already on a ticker page (ticker→ticker nav)
        // to avoid stacking up ghost ticker entries the back button walks through.
        const alreadyOnTicker =
            typeof window !== "undefined" &&
            window.location.pathname.startsWith("/ticker/");
        syncRoute(`/ticker/${encodeURIComponent(symbol)}`, options.replace === true || alreadyOnTicker);
    }, [syncRoute]);

    const handleTechnoFundaScan = ({ label, tickers }, source = "screens") => {
        setTechnoFundaFilter({ label, tickers });
        setTechnoFundaSource(source);
        setProductTab("financial");
        setFinancialSubPage("screener");
    };

    const openTopbarFinancialSearch = (payload) => {
        setTechnoFundaFilter(null);
        setTechnoFundaSource(null);
        setProductTab("financial");
        setFinancialSubPage("search");
        setOpenDropdown(null);
        setTopbarSearchRequest({ ...payload, key: Date.now() + Math.random() });
    };

    const applyAppRouteState = useCallback((parsed) => {
        setProductTab(parsed.productTab || DEFAULT_APP_STATE.productTab);
        setPage(parsed.page || DEFAULT_APP_STATE.page);
        setFinancialSubPage(parsed.financialSubPage || DEFAULT_APP_STATE.financialSubPage);
        setTechnicalSubPage(parsed.technicalSubPage || DEFAULT_APP_STATE.technicalSubPage);
        setLegalInitialTab(parsed.legalInitialTab || DEFAULT_APP_STATE.legalInitialTab);
        setTechnoFundaFilter(null);
        setTechnoFundaSource(null);
        setOpenDropdown(null);
    }, []);
    const [modal, setModal] = useState(null);
    const [checking, setChecking] = useState(true);
    const [railCollapsed, setRailCollapsed] = useState(true);   //  changed to true
    const [showProfileMenu, setShowProfileMenu] = useState(false);
    const [showLoginModal, setShowLoginModal] = useState(false);
    const journalPortfolioRefreshIdRef = useRef(0);
    const moversWarmupRef = useRef(false);

    //  NSE Bhav Copy 





    //  52-Week High/Low 
    const [w52Fetching, setW52Fetching] = useState(false);
    const [w52Status, setW52Status] = useState(null); // { ok, msg }
    const handleFetch52w = async () => {
        setW52Fetching(true); setW52Status({ ok: true, msg: " Starting..." });
        try {
            const result = await trigger52wFetch(
                session?.access_token,
                (msg) => setW52Status({ ok: true, msg: ` ${msg}` }),
            );
            const nse = result?.nse?.rows_inserted ?? 0;
            const bse = result?.bse?.rows_inserted ?? 0;
            if (nse === 0 && bse === 0) {
                const nseParsed = result?.nse?.rows_parsed ?? 0;
                const bseParsed = result?.bse?.rows_parsed ?? 0;
                if (nseParsed === 0 && bseParsed === 0) {
                    setW52Status({ ok: false, msg: ` CORS blocked  open NSE/BSE in a tab first, then retry` });
                } else {
                    setW52Status({ ok: false, msg: ` Parsed ${nseParsed} NSE + ${bseParsed} BSE but insert failed` });
                }
            } else {
                setW52Status({ ok: true, msg: ` 52W H/L: ${nse} NSE + ${bse} BSE for ${result?.date ?? "today"}` });
            }
        } catch (e) {
            setW52Status({ ok: false, msg: ` ${e.message}` });
        }
        setW52Fetching(false);
        setTimeout(() => setW52Status(null), 15000);
    };

    const [theme, setTheme] = useState(() => {
        try { return localStorage.getItem("tv_theme") || "light"; } catch { return "light"; }
    });

    useEffect(() => {
        if (session?.access_token && session?.user?.id) savePersistedSession(session);
        else clearPersistedSession();
    }, [session]);
    const T = THEMES[theme];
    const journalTradeRows = useMemo(() => buildTradeRows(trades), [trades]);
    const journalStats = useMemo(() => calcStatsFromRows(journalTradeRows), [journalTradeRows]);
    const journalCapitalGainsRows = useMemo(() => calcCapitalGainsFromRows(journalTradeRows), [journalTradeRows]);

    useEffect(() => {
        if (checking) return;
        if (moversWarmupRef.current) return;
        moversWarmupRef.current = true;
        void warmStockDashboardCaches(session?.access_token || null).catch(err => {
            console.warn("[StockDashboard warmup] failed:", err?.message || err);
        });
    }, [checking, session?.access_token]);

    const toggleTheme = () => {
        const next = theme === "dark" ? "light" : "dark";
        setTheme(next);
        try { localStorage.setItem("tv_theme", next); } catch { }
    };

    const loadTrades = async (sess) => {
        try {
            const db = await supabase.db("trades", sess.access_token);
            const data = await db.select();
            if (Array.isArray(data)) {
                setTrades(data);
                //  Background: refresh shareholding for all portfolio tickers 
                // Uses existing fetch-shareholding edge function (IndianAPI).
                // Checks DB freshness first (7-day threshold)  only fetches stale ones.
                // Fires sequentially with 1s gap to avoid hammering IndianAPI rate limits.
                const tickers = [...new Set(data.map(t => t.ticker).filter(Boolean))];
                if (tickers.length > 0) {
                    (async () => {
                        // Check which tickers have stale/missing shareholding data
                        try {
                            const cutoff = new Date(Date.now() - 7 * 86400000).toISOString();
                            const staleRes = await fetch(
                                `${SUPABASE_URL}/rest/v1/shareholding_pattern` +
                                `?ticker=in.(${tickers.map(t => `"${t}"`).join(",")})` +
                                `&select=ticker,fetched_at&order=ticker.asc,fetched_at.desc`,
                                { headers: supabase._h(sess.access_token) }
                            );
                            const existing = staleRes.ok ? await staleRes.json() : [];
                            // Keep only the most recent row per ticker
                            const latestByTicker = {};
                            for (const row of (Array.isArray(existing) ? existing : [])) {
                                if (!latestByTicker[row.ticker] || row.fetched_at > latestByTicker[row.ticker])
                                    latestByTicker[row.ticker] = row.fetched_at;
                            }
                            const stale = tickers.filter(t => !latestByTicker[t] || latestByTicker[t] < cutoff);
                            console.log(`[SHP] ${stale.length}/${tickers.length} tickers need refresh:`, stale);
                            for (const ticker of stale) {
                                try {
                                    await fetch(`${SUPABASE_URL}/functions/v1/fetch-shareholding`, {
                                        method: "POST",
                                        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${SUPABASE_ANON_KEY}` },
                                        body: JSON.stringify({ ticker }),
                                        signal: AbortSignal.timeout(30000),
                                    });
                                } catch (e) { console.warn(`[SHP] ${ticker} failed:`, e.message); }
                                await new Promise(r => setTimeout(r, 1000));
                            }
                            console.log("[SHP] Background refresh complete");
                        } catch (e) { console.warn("[SHP] Background refresh error:", e.message); }
                    })();
                }
            }
        } catch (e) { console.error(e); }
        // Preload screener data in background so it's instant when user navigates there
        _preloadScreenerCache();
        // Preload breadth data (company_financials) in background  most expensive part
        if (!_breadthCache.cfRows) {
            const H = { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` };
            const fetchAllPages = async (baseUrl, pageSize = 5000) => {
                const firstRes = await fetch(`${baseUrl}&limit=${pageSize}&offset=0`, { headers: { ...H, "Range-Unit": "items" } });
                const first = await firstRes.json();
                if (!Array.isArray(first) || first.length < pageSize) return Array.isArray(first) ? first : [];
                const extraPages = await Promise.all(
                    [1, 2, 3, 4, 5, 6, 7, 8, 9].map(p =>
                        fetch(`${baseUrl}&limit=${pageSize}&offset=${p * pageSize}`, { headers: { ...H, "Range-Unit": "items" } })
                            .then(r => r.json()).catch(() => [])
                    )
                );
                let all = [...first];
                for (const page of extraPages) {
                    if (!Array.isArray(page) || page.length === 0) break;
                    all = all.concat(page);
                    if (page.length < pageSize) break;
                }
                return all;
            };
            fetchAllPages(`${SUPABASE_URL}/rest/v1/company_financials?exchange=eq.NSE&select=ticker,market_cap_cr,industry,name`)
                .then(rows => { _breadthCache.cfRows = rows; _breadthCache.cfRowsTime = Date.now(); })
                .catch(() => { });
        }
    };

    const loadFunds = async (sess) => {
        try {
            const h = supabase._h(sess.access_token);
            const r = await fetch(`${SUPABASE_URL}/rest/v1/funds?select=*&order=date.asc&user_id=eq.${sess.user?.id}`, { headers: h });
            const data = await r.json();
            if (Array.isArray(data)) setFunds(data);
        } catch (e) { console.error(e); }
    };

    const loadDividends = async (sess) => {
        try {
            const h = supabase._h(sess.access_token);
            const r = await fetch(`${SUPABASE_URL}/rest/v1/dividends?select=*&order=date.asc&user_id=eq.${sess.user?.id}`, { headers: h });
            const data = await r.json();
            if (Array.isArray(data)) setDividends(data);
        } catch (e) { console.error(e); }
    };

    // ── Guest data helpers (localStorage) ────────────────────────────────────
    const GUEST_LS_KEY = "te_guest_journal";
    const saveGuestData = (t, f, d) => {
        try { localStorage.setItem(GUEST_LS_KEY, JSON.stringify({ trades: t, funds: f, dividends: d })); } catch { }
    };
    const loadGuestData = () => {
        try {
            const raw = localStorage.getItem(GUEST_LS_KEY);
            if (!raw) return null;
            return JSON.parse(raw);
        } catch { return null; }
    };
    const clearGuestData = () => { try { localStorage.removeItem(GUEST_LS_KEY); } catch { } };

    // Auto-save guest data whenever trades/funds/dividends change (only when not logged in and not demo)
    useEffect(() => {
        if (!session && !isDemo) {
            saveGuestData(trades, funds, dividends);
        }
    }, [trades, funds, dividends, session, isDemo]);

    useEffect(() => {
        supabase.auth.getSessionFromHash().then(sess => {
            if (sess?.access_token && sess.user?.id) {
                supabase._session = sess;
                setSession(sess);
                loadTrades(sess); loadFunds(sess); loadDividends(sess);
                setChecking(false);
                return;
            }

            const persisted = loadPersistedSession();
            if (persisted?.access_token && persisted.user?.id) {
                supabase._session = persisted;
                setSession(persisted);
                loadTrades(persisted); loadFunds(persisted); loadDividends(persisted);
                setChecking(false);
                return;
            }

            // No session – load any previously saved guest data
            const guest = loadGuestData();
            if (guest) {
                if (Array.isArray(guest.trades)) setTrades(guest.trades);
                if (Array.isArray(guest.funds)) setFunds(guest.funds);
                if (Array.isArray(guest.dividends)) setDividends(guest.dividends);
            }
            setChecking(false);
        });
    }, []);

    const handleLogin = async (sess) => {
        if (!sess?.access_token || !sess.user?.id) return;
        supabase._session = sess;
        setSession(sess);
        setIsDemo(false);

        // Upload any guest trades/funds/dividends to Supabase before reloading
        const guest = loadGuestData();
        if (guest) {
            const h = supabase._h(sess.access_token);
            try {
                if (Array.isArray(guest.trades) && guest.trades.length) {
                    const payload = guest.trades.map(({ id, ...t }) => ({ ...t, user_id: sess.user.id }));
                    await fetch(`${SUPABASE_URL}/rest/v1/trades`, { method: "POST", headers: { ...h, Prefer: "return=minimal" }, body: JSON.stringify(payload) });
                }
                if (Array.isArray(guest.funds) && guest.funds.length) {
                    const payload = guest.funds.map(({ id, ...f }) => ({ ...f, user_id: sess.user.id }));
                    await fetch(`${SUPABASE_URL}/rest/v1/funds`, { method: "POST", headers: { ...h, Prefer: "return=minimal" }, body: JSON.stringify(payload) });
                }
                if (Array.isArray(guest.dividends) && guest.dividends.length) {
                    const payload = guest.dividends.map(({ id, ...d }) => ({ ...d, user_id: sess.user.id }));
                    await fetch(`${SUPABASE_URL}/rest/v1/dividends`, { method: "POST", headers: { ...h, Prefer: "return=minimal" }, body: JSON.stringify(payload) });
                }
            } catch (e) { console.warn("[Guest sync] Upload error:", e); }
            clearGuestData();
        }

        loadTrades(sess); loadFunds(sess); loadDividends(sess);
    };

    const handleDemo = () => {
        setIsDemo(true);
        setTrades(DEMO_TRADES);
        setFunds(DEMO_FUNDS);
        setDividends([]);
        setProductTab(SAFE_PRODUCT_TAB);
        setPage("dashboard");
        setSession({ email: "demo@tradeedge.app" });
    };

    const handleLogout = () => {
        supabase._session = null;
        setSession(null);
        setIsDemo(false);
        setProductTab(SAFE_PRODUCT_TAB);
        setPage("dashboard");
        // Restore guest data (if any) after logout
        const guest = loadGuestData();
        if (guest) {
            setTrades(Array.isArray(guest.trades) ? guest.trades : []);
            setFunds(Array.isArray(guest.funds) ? guest.funds : []);
            setDividends(Array.isArray(guest.dividends) ? guest.dividends : []);
        } else {
            setTrades([]); setFunds([]); setDividends([]);
        }
    };

    const handleSave = async (form) => {
        // _tab is a UI-only hint, not a DB field
        const { _tab, ...formData } = form;
        form = formData;
        const ticker = form.ticker.toUpperCase();
        const buy_qty = parseFloat(form.buy_qty);
        const buy_price = parseFloat(form.buy_price);
        const sell_qty = form.sell_qty ? parseFloat(form.sell_qty) : null;
        const sell_price = form.sell_price ? parseFloat(form.sell_price) : null;
        const exit_date = form.exit_date || null;

        //  GUARD: cannot sell more than the available open qty 
        if (_tab === "sell" && sell_qty && sell_qty > buy_qty) {
            alert(`Sell qty (${sell_qty}) exceeds available open qty (${buy_qty}). Please enter a valid quantity.`);
            return;
        }

        //  PARTIAL SELL: sell_qty < buy_qty  split into closed + open remainder 
        const isPartialSell = exit_date && sell_qty && sell_qty < buy_qty;

        const closedData = {
            ticker,
            entry_date: form.entry_date,
            buy_qty: isPartialSell ? sell_qty : buy_qty,
            buy_price,
            exit_date,
            sell_qty: sell_qty,
            sell_price,
        };

        const remainderData = isPartialSell ? {
            ticker,
            entry_date: form.entry_date,
            buy_qty: buy_qty - sell_qty,
            buy_price,
            exit_date: null,
            sell_qty: null,
            sell_price: null,
        } : null;

        if (isDemo) {
            if (modal.mode === "add") {
                const newTrades = [{ ...closedData, id: Date.now() }];
                if (remainderData) newTrades.push({ ...remainderData, id: Date.now() + 1 });
                setTrades(t => [...t, ...newTrades]);
            } else {
                // Replace original with closed portion, and add open remainder if partial
                setTrades(t => {
                    const updated = t.map(tr => tr.id === modal.trade.id ? { ...closedData, id: tr.id } : tr);
                    if (remainderData) return [...updated, { ...remainderData, id: Date.now() }];
                    return updated;
                });
            }
        } else {
            const db = await supabase.db("trades", session.access_token);
            if (modal.mode === "add") {
                const res = await db.insert({ ...closedData, user_id: session.user?.id });
                if (remainderData) await db.insert({ ...remainderData, user_id: session.user?.id });
                if (!remainderData && Array.isArray(res)) setTrades(t => [...t, ...res]);
                else loadTrades(session);
            } else {
                await db.update(modal.trade.id, closedData);
                if (remainderData) await db.insert({ ...remainderData, user_id: session.user?.id });
                loadTrades(session);
            }
        }
        setModal(null);
    };

    const handleDelete = async (id) => {
        if (!window.confirm("Delete this trade?")) return;
        if (isDemo) { setTrades(t => t.filter(tr => tr.id !== id)); return; }
        const db = await supabase.db("trades", session.access_token);
        await db.delete(id); setTrades(t => t.filter(tr => tr.id !== id));
    };

    const handleFundSave = async (data, existing) => {
        const payload = { date: data.date, amount: parseFloat(data.amount), type: data.type, dp: data.dp, note: data.note || "" };
        if (isDemo) {
            if (existing) setFunds(f => f.map(x => x.id === existing.id ? { ...payload, id: x.id } : x));
            else setFunds(f => [...f, { ...payload, id: Date.now() }]);
            return;
        }
        const h = supabase._h(session.access_token);
        if (existing) {
            await fetch(`${SUPABASE_URL}/rest/v1/funds?id=eq.${existing.id}`, { method: "PATCH", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify(payload) });
        } else {
            await fetch(`${SUPABASE_URL}/rest/v1/funds`, { method: "POST", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify({ ...payload, user_id: session.user?.id }) });
        }
        loadFunds(session);
    };

    const handleFundDelete = async (id) => {
        if (!window.confirm("Delete this entry?")) return;
        if (isDemo) { setFunds(f => f.filter(x => x.id !== id)); return; }
        const h = supabase._h(session.access_token);
        await fetch(`${SUPABASE_URL}/rest/v1/funds?id=eq.${id}`, { method: "DELETE", headers: h });
        setFunds(f => f.filter(x => x.id !== id));
    };

    const handleFundBulkDelete = async (ids) => {
        if (isDemo) { setFunds(f => f.filter(x => !ids.includes(x.id))); return; }
        const h = supabase._h(session.access_token);
        await Promise.all(ids.map(id => fetch(`${SUPABASE_URL}/rest/v1/funds?id=eq.${id}`, { method: "DELETE", headers: h })));
        setFunds(f => f.filter(x => !ids.includes(x.id)));
    };

    const handleFundImportCSV = async (rows) => {
        if (isDemo) {
            const demo = rows.map((r, i) => ({ ...r, id: Date.now() + i }));
            setFunds(f => [...f, ...demo]);
            return;
        }
        const h = supabase._h(session.access_token);
        const payload = rows.map(r => ({ ...r, user_id: session.user?.id }));
        console.log("Importing rows:", payload.length, "Sample:", payload[0]);
        const res = await fetch(`${SUPABASE_URL}/rest/v1/funds`, { method: "POST", headers: { ...h, Prefer: "return=minimal" }, body: JSON.stringify(payload) });
        console.log("Supabase response status:", res.status, res.statusText);
        if (!res.ok) {
            const err = await res.text();
            console.error("Bulk insert error:", err);
            throw new Error(err);
        }
        await loadFunds(session);
    };

    const handleDividendSave = async (data, existing) => {
        const payload = { ticker: data.ticker, date: data.date, amount: parseFloat(data.amount), fy: data.fy, note: data.note || "" };
        if (isDemo) {
            if (existing) setDividends(d => d.map(x => x.id === existing.id ? { ...payload, id: x.id } : x));
            else setDividends(d => [...d, { ...payload, id: Date.now() }]);
            return;
        }
        const h = supabase._h(session.access_token);
        if (existing) {
            await fetch(`${SUPABASE_URL}/rest/v1/dividends?id=eq.${existing.id}`, { method: "PATCH", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify(payload) });
        } else {
            await fetch(`${SUPABASE_URL}/rest/v1/dividends`, { method: "POST", headers: { ...h, Prefer: "return=representation" }, body: JSON.stringify({ ...payload, user_id: session.user?.id }) });
        }
        loadDividends(session);
    };

    const handleDividendDelete = async (id, skipConfirm = false) => {
        if (!skipConfirm && !window.confirm("Delete this dividend entry?")) return;
        if (isDemo) { setDividends(d => d.filter(x => x.id !== id)); return; }
        const h = supabase._h(session.access_token);
        await fetch(`${SUPABASE_URL}/rest/v1/dividends?id=eq.${id}`, { method: "DELETE", headers: h });
        setDividends(d => d.filter(x => x.id !== id));
    };

    const handleDividendImportCSV = async (rows) => {
        if (isDemo) {
            const demo = rows.map((r, i) => ({ ...r, id: Date.now() + i }));
            setDividends(d => [...d, ...demo]);
            return;
        }
        const h = supabase._h(session.access_token);
        const payload = rows.map(r => ({ ...r, user_id: session.user?.id }));
        const res = await fetch(`${SUPABASE_URL}/rest/v1/dividends`, { method: "POST", headers: { ...h, Prefer: "return=minimal" }, body: JSON.stringify(payload) });
        if (!res.ok) { const err = await res.text(); console.error("Dividend import error:", err); throw new Error(err); }
        await loadDividends(session);
    };

    const handleImportCSV = async (row) => {
        const data = { ticker: row.ticker, entry_date: row.entry_date, buy_qty: row.buy_qty, buy_price: row.buy_price, exit_date: row.exit_date || null, sell_qty: row.sell_qty || null, sell_price: row.sell_price || null };
        if (isDemo) { setTrades(t => [...t, { ...data, id: Date.now() + Math.random() }]); return; }
        const db = await supabase.db("trades", session.access_token);
        const res = await db.insert({ ...data, user_id: session.user?.id });
        if (Array.isArray(res) && res[0]) setTrades(t => [...t, res[0]]);
        else throw new Error("Insert failed");
    };


    //  NAV STRUCTURE
    const NAV_ITEMS = [
        {
            id: "dashboard", label: "Dashboard", section: "Markets",
            icon: (
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"
                    strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="3" y="3" width="7" height="7" />
                    <rect x="14" y="3" width="7" height="7" />
                    <rect x="3" y="14" width="7" height="7" />
                    <rect x="14" y="14" width="7" height="7" />
                </svg>
            ),
        },
        {
            id: "watchlist", label: "Watchlist", section: "Markets",
            icon: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" /><polyline points="9 22 9 12 15 12 15 22" /></svg>,
        },
        {
            id: "financial", label: "Fundamentals", section: "Markets",
            icon: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="3" width="5" height="18" /><rect x="9.5" y="8" width="5" height="13" /><rect x="17" y="13" width="5" height="8" /></svg>,
            subItems: [
                { id: "screener", label: "Screener", description: "Filter the market with structured factor and quality rules." },
                { id: "fiidii", label: "FII / DII Flow", description: "Track institutional cash and derivatives participation." },
                { id: "ownership", label: "Ownership Scans", description: "Review promoter, fund, and shareholder positioning." },
                { id: "announcements", label: "Announcements", description: "Track corporate disclosures and regulatory filings in real time." },
            ],
        },
        {
            id: "technical", label: "Technicals", section: "Markets",
            icon: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17" /><polyline points="16 7 22 7 22 13" /></svg>,
            subItems: [
                { id: "breadth", label: "Market Breadth", description: "Read trend participation and internal market strength." },
                { id: "screens", label: "Screens", description: "Surface technical setups, breakouts, and pullbacks." },
                { id: "heatmap", label: "Heatmap", description: "Scan sector and stock performance concentration quickly." },
                { id: "rotation", label: "Sector Rotation (RRG)", description: "Compare leadership rotation across sector groups." },
            ],
        },
        {
            id: "tradevault", label: "Journal", section: "My Portfolio",
            icon: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><polyline points="14 2 14 8 20 8" /></svg>,
            subItems: [
                { id: "dashboard", label: "Dashboard", description: "Open your portfolio summary and recent activity." },
                { id: "trades", label: "Trade Journal", description: "Record entries, exits, and execution notes." },
                { id: "analytics", label: "Analytics", description: "Review win rate, expectancy, and trading patterns." },
                { id: "capital-gains", label: "Capital Gains", description: "Inspect realized P&L across Indian financial years." },
                { id: "funds", label: "Funds & XIRR", description: "Track capital flows, cash, and return efficiency." },
                { id: "dividends", label: "Dividends", description: "Audit dividend receipts and income history." },
            ]
        },
    ];

    const emailDisplay = isDemo ? "demo@tradeedge.app" : (session?.user?.email || session?.email || "Guest");
    const isLight = theme === "light";
    const D = !isLight;

    // Breadcrumb
    const activeNavItem = NAV_ITEMS.find(n => n.id === productTab);
    const activeSubItem = productTab === "financial"
        ? activeNavItem?.subItems?.find(s => s.id === financialSubPage)
        : productTab === "technical"
            ? activeNavItem?.subItems?.find(s => s.id === technicalSubPage)
            : activeNavItem?.subItems?.find(s => s.id === page);
    const breadcrumb = route.kind === "ticker"
        ? ["Fundamentals", route.symbol]
        : activeSubItem
            ? [activeNavItem?.label, activeSubItem?.label]
            : [activeNavItem?.label];
    const activeContextLabel = breadcrumb.filter(Boolean).join(" / ") || "Workspace";
    const activeSectionLabel = activeNavItem?.section || "Workspace";
    const seoProfile = useMemo(() => getSeoProfile({
        route,
        productTab,
        financialSubPage,
        technicalSubPage,
        page,
        legalInitialTab,
    }), [route, productTab, financialSubPage, technicalSubPage, page, legalInitialTab]);

    useEffect(() => {
        const handlePopState = () => {
            const parsed = parseAppRoute(window.location.pathname);
            restoringHistoryRef.current = true;
            setRoute(parsed);
            // Clear stale ticker state when back-navigating away from a ticker route
            if (parsed.kind === "app") {
                setTopbarSearch("");
                topbarResolvedSymRef.current = null;
                applyAppRouteState(parsed);
            }
        };
        window.addEventListener("popstate", handlePopState);
        return () => window.removeEventListener("popstate", handlePopState);
    }, [applyAppRouteState]);

    useEffect(() => {
        if (route.kind === "ticker") return;
        const nextPath = appPathFromState({ productTab, page, financialSubPage, technicalSubPage, legalInitialTab });
        if (typeof window === "undefined" || window.location.pathname === nextPath) {
            restoringHistoryRef.current = false;
            return;
        }
        if (restoringHistoryRef.current) {
            restoringHistoryRef.current = false;
            return;
        }
        window.history.pushState(null, "", nextPath);
        setRoute(parseAppRoute(nextPath));
    }, [route.kind, productTab, page, financialSubPage, technicalSubPage, legalInitialTab]);

    useEffect(() => {
        if (route.kind !== "ticker" || !route.symbol) return;
        setProductTab("financial");
        setFinancialSubPage("search");
        setTechnoFundaFilter(null);
        setTechnoFundaSource(null);
        setTopbarSearch(route.symbol);
        topbarResolvedSymRef.current = route.symbol;
    }, [route.kind, route.symbol]);

    useEffect(() => {
        updateSeoMetadata(seoProfile, theme);
    }, [seoProfile, theme]);

    useEffect(() => {
        if (!topbarSearch.trim()) {
            setTopbarSuggestions([]);
            setShowTopbarSuggestions(false);
            setActiveTopbarSuggIdx(-1);
            return;
        }
        clearTimeout(topbarSearchTimerRef.current);
        topbarSearchTimerRef.current = setTimeout(async () => {
            const results = await fetchFinancialAutocompleteSuggestions(topbarSearch);
            setTopbarSuggestions(results);
            setActiveTopbarSuggIdx(-1);
            setShowTopbarSuggestions(results.length > 0);
        }, 140);
        return () => clearTimeout(topbarSearchTimerRef.current);
    }, [topbarSearch]);

    useEffect(() => {
        if (!showTopbarSuggestions) return;
        const handlePointerDown = (event) => {
            const target = event.target;
            if (topbarSearchWrapRef.current?.contains(target)) return;
            if (topbarSearchDropdownRef.current?.contains(target)) return;
            setShowTopbarSuggestions(false);
        };
        const handleEscape = (event) => {
            if (event.key === "Escape") setShowTopbarSuggestions(false);
        };
        window.addEventListener("mousedown", handlePointerDown);
        window.addEventListener("keydown", handleEscape);
        return () => {
            window.removeEventListener("mousedown", handlePointerDown);
            window.removeEventListener("keydown", handleEscape);
        };
    }, [showTopbarSuggestions]);

    const submitTopbarSearch = async (picked = null) => {
        let selected = picked || (activeTopbarSuggIdx >= 0 ? topbarSuggestions[activeTopbarSuggIdx] : null);
        if (!selected) {
            const query = (topbarResolvedSymRef.current || topbarSearch).trim();
            if (!query) return;
            if (topbarResolvedSymRef.current) {
                selected = { sym: topbarResolvedSymRef.current, name: topbarResolvedSymRef.current };
            } else {
                const matches = topbarSuggestions.length ? topbarSuggestions : await fetchFinancialAutocompleteSuggestions(query);
                selected = matches[0] || { sym: query.toUpperCase(), name: query.toUpperCase() };
            }
        }
        topbarResolvedSymRef.current = selected.sym;
        setTopbarSearch(selected.name || selected.sym);
        setTopbarSuggestions([]);
        setShowTopbarSuggestions(false);
        navigateToTicker(selected.sym);
    };

    if (checking) return (
        <>
            <style>{`body{background:${T.bg};display:flex;align-items:center;justify-content:center;height:100vh;margin:0;font-family:'DM Sans',sans-serif;color:${T.subtext};font-size:14px}`}</style>
            <div>Loading...</div>
        </>
    );

    // Dashboard always renders; login is triggered via modal from the top-nav Login button

    // Group nav items by section
    const sections = [];
    NAV_ITEMS.forEach(item => {
        const existing = sections.find(s => s.label === item.section);
        if (existing) existing.items.push(item);
        else sections.push({ label: item.section, items: [item] });
    });

    return (
        <>
            <style>{makeCSS(T)}</style>
            <div className="app-shell">

                {/* 
                    TOP NAVIGATION BAR
                 */}
                <nav className="top-nav">
                    <button
                        className="top-nav-mobile-menu-btn"
                        aria-label={railCollapsed ? "Open navigation menu" : "Close navigation menu"}
                        onClick={() => setRailCollapsed(c => !c)}
                    >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round">
                            {railCollapsed
                                ? <><line x1="4" y1="7" x2="20" y2="7" /><line x1="4" y1="12" x2="20" y2="12" /><line x1="4" y1="17" x2="20" y2="17" /></>
                                : <><line x1="6" y1="6" x2="18" y2="18" /><line x1="18" y1="6" x2="6" y2="18" /></>}
                        </svg>
                    </button>

                    <div className="top-nav-brand">
                        <div className="top-nav-logo">
                            <div className="top-nav-logo-mark">
                                <img src={BRAND_LOGO_SRC} alt="" aria-hidden="true" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                            </div>
                            <div className="top-nav-logo-copy">
                                <span className="top-nav-logo-text"><span className="logo-trade">TRADE</span><span className="logo-edge">EDGE</span></span>
                            </div>
                        </div>
                    </div>

                    <div className="top-nav-center">
                        <div className="top-nav-search-wrap" ref={topbarSearchWrapRef}>
                            <div className="top-nav-panel">
                                <svg className="top-nav-search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <circle cx="11" cy="11" r="7" />
                                    <path d="M20 20l-3.5-3.5" />
                                </svg>
                                <input
                                    className="top-nav-search-input"
                                    value={topbarSearch}
                                    onChange={e => {
                                        const v = e.target.value.toUpperCase();
                                        setTopbarSearch(v);
                                        topbarResolvedSymRef.current = null;
                                        if (v.trim()) setShowTopbarSuggestions(true);
                                    }}
                                    onFocus={() => {
                                        if (topbarSuggestions.length > 0) setShowTopbarSuggestions(true);
                                    }}
                                    onKeyDown={e => {
                                        if (e.key === "ArrowDown") {
                                            e.preventDefault();
                                            setActiveTopbarSuggIdx(i => Math.min(i + 1, topbarSuggestions.length - 1));
                                            setShowTopbarSuggestions(topbarSuggestions.length > 0);
                                        } else if (e.key === "ArrowUp") {
                                            e.preventDefault();
                                            setActiveTopbarSuggIdx(i => Math.max(i - 1, 0));
                                        } else if (e.key === "Enter") {
                                            e.preventDefault();
                                            submitTopbarSearch();
                                        } else if (e.key === "Escape") {
                                            setShowTopbarSuggestions(false);
                                        }
                                    }}
                                    placeholder="Search ticker or company"
                                    autoCapitalize="characters"
                                    autoComplete="off"
                                />
                                <button className="top-nav-search-action" onClick={() => submitTopbarSearch()} type="button">
                                    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                        <circle cx="11" cy="11" r="7" /><path d="M20 20l-3.5-3.5" />
                                    </svg>
                                    <span>Go</span>
                                </button>
                            </div>
                            {showTopbarSuggestions && topbarSuggestions.length > 0 && (
                                <div className="top-nav-search-sugg" ref={topbarSearchDropdownRef}>
                                    <div className="top-nav-search-sugg-header">Ticker Matches</div>
                                    {topbarSuggestions.map((s, i) => (
                                        <div
                                            key={`${s.sym}-${s.exchange || "any"}`}
                                            className={`top-nav-search-sugg-item${i === activeTopbarSuggIdx ? " active" : ""}`}
                                            onMouseDown={() => submitTopbarSearch(s)}
                                            onMouseEnter={() => setActiveTopbarSuggIdx(i)}
                                        >
                                            <span className="top-nav-search-sugg-dot">{(s.sym || "?").charAt(0)}</span>
                                            <div className="top-nav-search-sugg-copy">
                                                <span className="top-nav-search-sugg-title">{s.name || s.sym}</span>
                                                <span className="top-nav-search-sugg-meta">
                                                    {s.sym}
                                                </span>
                                            </div>
                                            {s.exchange && <span className="top-nav-search-sugg-exchange-badge">{s.exchange}</span>}
                                        </div>
                                    ))}
                                    <div className="top-nav-search-sugg-footer" onMouseDown={() => submitTopbarSearch()}>
                                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                                            <circle cx="11" cy="11" r="7" />
                                            <path d="M20 20l-3.5-3.5" />
                                        </svg>
                                        Search fundamentals for <strong>{topbarSearch.trim()}</strong>
                                    </div>
                                </div>
                            )}
                        </div>
                        <div className="top-nav-items">
                            {sections.map(section => (
                                <div className="top-nav-group" key={section.label}>
                                    {section.items.map(item => (
                                        <TopNavItem
                                            key={item.id}
                                            item={item}
                                            productTab={productTab}
                                            financialSubPage={financialSubPage}
                                            technicalSubPage={technicalSubPage}
                                            page={page}
                                            setProductTab={setProductTab}
                                            setFinancialSubPage={setFinancialSubPage}
                                            setTechnicalSubPage={setTechnicalSubPage}
                                            setPage={setPage}
                                            setTechnoFundaFilter={setTechnoFundaFilter}
                                            setTechnoFundaSource={setTechnoFundaSource}
                                            clearTickerRoute={clearTickerRoute}
                                            prefetchFinancialTabs={() => {
                                                prefetchFiiDiiData();
                                                prefetchOwnershipData();
                                            }}
                                            prefetchFiiDii={prefetchFiiDiiData}
                                            prefetchOwnership={prefetchOwnershipData}
                                            openDropdown={openDropdown}
                                            setOpenDropdown={setOpenDropdown}
                                            onAuthRequired={() => setShowLoginModal(true)}
                                            isAuthenticated={!!(session || isDemo)}
                                        />
                                    ))}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="top-nav-actions">
                        {isDemo && (
                            <div className="demo-banner">
                                <svg width="9" height="9" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z" /></svg>
                                Demo
                            </div>
                        )}
                        {session || isDemo ? (
                            <>
                                {/* Profile popup */}
                                {showProfileMenu && (
                                    <>
                                        <div style={{ position: "fixed", inset: 0, zIndex: 9998 }} onClick={() => setShowProfileMenu(false)} />
                                        <TopNavProfilePopup
                                            emailDisplay={emailDisplay}
                                            isDemo={isDemo}
                                            isLight={isLight}
                                            toggleTheme={toggleTheme}
                                            handleLogout={handleLogout}
                                            setShowProfileMenu={setShowProfileMenu}
                                        />
                                    </>
                                )}
                                {/* User avatar icon */}
                                <div
                                    className={`top-nav-user-chip${showProfileMenu ? " open" : ""}`}
                                    onClick={() => setShowProfileMenu(m => !m)}
                                >
                                    <div className="top-nav-user-avatar">{emailDisplay[0].toUpperCase()}</div>
                                    <svg
                                        width="12" height="12" viewBox="0 0 24 24" fill="none"
                                        stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
                                        style={{
                                            opacity: 0.6,
                                            transform: showProfileMenu ? 'rotate(180deg)' : 'none',
                                            transition: 'transform 0.2s ease'
                                        }}
                                    >
                                        <polyline points="6 9 12 15 18 9" />
                                    </svg>
                                </div>
                            </>
                        ) : (
                            /* Login button shown when not authenticated */
                            <button
                                onClick={() => setShowLoginModal(true)}
                                style={{
                                    display: "flex",
                                    alignItems: "center",
                                    gap: 7,
                                    padding: "7px 16px",
                                    background: "linear-gradient(135deg,#059669,#1d4ed8)",
                                    border: "none",
                                    borderRadius: 8,
                                    color: "#fff",
                                    fontSize: 13,
                                    fontWeight: 600,
                                    fontFamily: "inherit",
                                    cursor: "pointer",
                                    boxShadow: "0 2px 8px rgba(5,150,105,0.30)",
                                    transition: "opacity .15s, transform .1s",
                                    whiteSpace: "nowrap",
                                }}
                                onMouseOver={e => e.currentTarget.style.opacity = ".88"}
                                onMouseOut={e => e.currentTarget.style.opacity = "1"}
                            >
                                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                                    <circle cx="12" cy="8" r="4" />
                                    <path d="M4 20c0-4 3.6-7 8-7s8 3 8 7" />
                                </svg>
                                Login
                            </button>
                        )}
                    </div>
                </nav>

                {/* Mobile full-screen nav drawer */}
                <div className={`top-nav-mobile-drawer${!railCollapsed ? " open" : ""}`}>
                    {isDemo && (
                        <div style={{ padding: "10px 18px" }}>
                            <div className="demo-banner" style={{ display: "inline-flex" }}>
                                <svg width="9" height="9" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z" /></svg>
                                Demo Mode
                            </div>
                        </div>
                    )}
                    {sections.map((section, si) => (
                        <div key={section.label}>
                            {si > 0 && <div className="top-nav-mobile-sep" />}
                            <div className="top-nav-mobile-section-label">{section.label}</div>
                            {section.items.map(item => (
                                <div key={item.id}>
                                    <div
                                        className={`top-nav-mobile-item${productTab === item.id ? " active" : ""}`}
                                        onClick={() => {
                                            if (item.soon) return;
                                            // Protected tab guard for mobile
                                            if (!(session || isDemo) && PROTECTED_TABS.has(item.id)) {
                                                setRailCollapsed(true);
                                                setShowLoginModal(true);
                                                return;
                                            }
                                            clearTickerRoute();
                                            setProductTab(item.id);
                                            if (item.id === "financial") {
                                                prefetchFiiDiiData();
                                                prefetchOwnershipData();
                                            }
                                            if (item.id === "financial" && financialSubPage === "search") {
                                                setFinancialSubPage(item.subItems?.[0]?.id || "screener");
                                            }
                                            if (!item.subItems) setRailCollapsed(true);
                                        }}
                                    >
                                        <span className="top-nav-mobile-item-icon">{item.icon}</span>
                                        {item.label}
                                        {item.subItems && <svg style={{ marginLeft: "auto", opacity: .4 }} width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg>}
                                    </div>
                                    {item.subItems && productTab === item.id && item.subItems.map(sub => (
                                        <div
                                            key={sub.id}
                                            className={`top-nav-mobile-sub${item.id === "financial" ? (financialSubPage === sub.id ? " active" : "")
                                                    : item.id === "technical" ? (technicalSubPage === sub.id ? " active" : "")
                                                        : page === sub.id ? " active" : ""
                                                }`}
                                            onClick={() => {
                                                clearTickerRoute();
                                                if (item.id === "financial") {
                                                    setFinancialSubPage(sub.id);
                                                    if (sub.id === "fiidii") prefetchFiiDiiData();
                                                    if (sub.id === "ownership") prefetchOwnershipData();
                                                    if (sub.id !== "screener") { setTechnoFundaFilter(null); setTechnoFundaSource(null); }
                                                }
                                                else if (item.id === "technical") setTechnicalSubPage(sub.id);
                                                else setPage(sub.id);
                                                setRailCollapsed(true);
                                            }}
                                        >
                                            <span style={{ width: 4, height: 4, borderRadius: "50%", background: "currentColor", opacity: .5, flexShrink: 0 }} />
                                            {sub.label}
                                        </div>
                                    ))}
                                </div>
                            ))}
                        </div>
                    ))}
                    {/* Mobile footer actions */}
                    <div className="top-nav-mobile-footer">
                        <div className="top-nav-mobile-item" onClick={() => { toggleTheme(); setRailCollapsed(true); }}>
                            <span className="top-nav-mobile-item-icon">T</span>
                            {isLight ? "Switch to Dark" : "Switch to Light"}
                        </div>
                        {session || isDemo ? (
                            <div className="top-nav-mobile-item" style={{ color: T.red }} onClick={() => { handleLogout(); setRailCollapsed(true); }}>
                                <span className="top-nav-mobile-item-icon">
                                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" /><polyline points="16 17 21 12 16 7" /><line x1="21" y1="12" x2="9" y2="12" /></svg>
                                </span>
                                Sign Out
                            </div>
                        ) : (
                            <div
                                className="top-nav-mobile-item"
                                style={{ color: T.green, fontWeight: 600 }}
                                onClick={() => { setShowLoginModal(true); setRailCollapsed(true); }}
                            >
                                <span className="top-nav-mobile-item-icon">
                                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        <circle cx="12" cy="8" r="4" />
                                        <path d="M4 20c0-4 3.6-7 8-7s8 3 8 7" />
                                    </svg>
                                </span>
                                Login
                            </div>
                        )}
                    </div>
                </div>

                {/* 
                    MAIN CONTENT AREA
                 */}
                <div className="main-area">

                    {/*  TOP COMMAND BAR  */}
                    <div className="top-bar">
                        <div className="top-breadcrumb">
                            <span>TradeEdge</span>
                            {breadcrumb.map((crumb, i) => (
                                <Fragment key={i}>
                                    <span className="top-breadcrumb-sep">&gt;</span>
                                    <span className={i === breadcrumb.length - 1 ? "top-breadcrumb-current" : ""}>{crumb}</span>
                                </Fragment>
                            ))}
                        </div>

                        <div className="top-bar-actions">
                        </div>
                    </div>

                    {/*  MODULE CONTENT  */}
                    <div className="content-area">

                        {productTab === "disclaimer" ? (
                            <LegalPage T={T} initialTab={legalInitialTab} onClose={closeLegal} />
                        ) : route.kind === "ticker" ? (
                            <PremiumTickerDashboard symbol={route.symbol} T={T} />
                        ) : (
                            <>

                                {/* JOURNAL MODULE */}
                                {productTab === "tradevault" && (
                                    <div className="journal-layout">
                                        <QuoteContext.Provider value={{ quotes, setQuotes }}>
                                            <main className="journal-main">
                                                <div className="journal-main-inner">
                                                    {page === "dashboard" && <Dashboard trades={trades} tradeRows={journalTradeRows} stats={journalStats} isDemo={isDemo} T={T} />}
                                                    {page === "trades" && <Trades trades={trades} tradeRows={journalTradeRows} onAdd={() => setModal({ mode: "add" })} onEdit={t => setModal({ mode: "edit", trade: t })} onDelete={handleDelete} onImportCSV={handleImportCSV} T={T} />}
                                                    {page === "analytics" && <Analytics trades={trades} tradeRows={journalTradeRows} stats={journalStats} T={T} />}
                                                    {page === "capital-gains" && <CapitalGains trades={trades} tradeRows={journalTradeRows} rows={journalCapitalGainsRows} T={T} />}
                                                    {page === "funds" && <Funds funds={funds} trades={trades} onSave={handleFundSave} onDelete={handleFundDelete} onBulkDelete={handleFundBulkDelete} onImportCSV={handleFundImportCSV} T={T} />}
                                                    {page === "dividends" && <Dividends dividends={dividends} onSave={handleDividendSave} onDelete={handleDividendDelete} onImportCSV={handleDividendImportCSV} T={T} />}
                                                </div>
                                            </main>
                                        </QuoteContext.Provider>
                                    </div>
                                )}

                                {/* WATCHLIST */}
                                {/* DASHBOARD */}
                                {productTab === "dashboard" && (
                                    <ModuleErrorBoundary
                                        T={T}
                                        moduleName="Market Dashboard"
                                        resetKey={`dashboard-${theme}`}
                                        onRecover={() => { setProductTab(SAFE_PRODUCT_TAB); setPage("dashboard"); }}
                                    >
                                        <StockDashboard
                                            T={T}
                                            userToken={session?.access_token}
                                            onTickerClick={(ticker) => {
                                                setTopbarSearch(ticker);
                                                topbarResolvedSymRef.current = ticker;
                                                navigateToTicker(ticker);
                                            }}
                                            onLogin={() => setShowLoginModal(true)}
                                            onNavigate={(tab, sub) => {
                                                if (tab === "technical") {
                                                    setProductTab("technical");
                                                    if (sub) setTechnicalSubPage(sub);
                                                } else if (tab === "financial") {
                                                    setProductTab("financial");
                                                    if (sub) setFinancialSubPage(sub);
                                                } else if (tab === "watchlist") {
                                                    setProductTab("watchlist");
                                                } else if (tab === "tradevault") {
                                                    setProductTab("tradevault");
                                                    if (sub) setPage(sub);
                                                }
                                            }}
                                        />
                                    </ModuleErrorBoundary>
                                )}
                                {productTab === "watchlist" && (
                                    <ModuleErrorBoundary
                                        T={T}
                                        moduleName="Watchlist"
                                        resetKey={`watchlist-${theme}`}
                                        onRecover={() => { setProductTab(SAFE_PRODUCT_TAB); setPage("dashboard"); }}
                                    >
                                        <WatchlistDashboard
                                            T={T}
                                            session={session}
                                            darkMode={theme === "dark"}
                                            onToggleDark={toggleTheme}
                                            onNavigateToScreen={(screenName) => {
                                                setTechnicalSubPage("screens");
                                                setProductTab("technical");
                                                window.__wl_openScreen = screenName;
                                            }}
                                            onTechnoFunda={({ label, tickers }) => {
                                                handleTechnoFundaScan({ label, tickers }, "watchlist");
                                            }}
                                            fetchAndCachePrice={_fetchAndCachePrice}
                                            bestPrice={_bestPrice}
                                            isPricePending={_isPricePending}
                                            isMarketLive={isMarketLive}
                                        />
                                    </ModuleErrorBoundary>
                                )}

                                {/* FUNDAMENTALS */}
                                {productTab === "financial" && (
                                    <div style={{ display: "flex", flex: 1, overflow: "hidden", background: T.bg, flexDirection: "column", minHeight: 0 }}>
                                        {financialSubPage === "search" && <FinancialAnalyticsModule T={T} externalSearchRequest={topbarSearchRequest} />}
                                        {financialSubPage === "screener" && (
                                            <div style={{ display: "flex", flex: 1, minHeight: 0, overflow: "hidden", flexDirection: "column", width: "100%" }}>
                                                <ScreenerModule
                                                    T={T}
                                                    session={session}
                                                    tickerFilter={technoFundaFilter?.tickers || null}
                                                    technoFundaLabel={technoFundaFilter?.label || null}
                                                    onClearTickerFilter={() => { setTechnoFundaFilter(null); setTechnoFundaSource(null); }}
                                                    onBack={technoFundaFilter ? () => {
                                                        setTechnoFundaFilter(null);
                                                        setTechnoFundaSource(null);
                                                        setFinancialSubPage("search");
                                                        if (technoFundaSource === "watchlist") {
                                                            setProductTab("watchlist");
                                                        } else {
                                                            setProductTab("technical");
                                                            setTechnicalSubPage("screens");
                                                        }
                                                    } : null}
                                                />
                                            </div>
                                        )}
                                        {financialSubPage === "fiidii" && (
                                            <div style={{ display: "flex", flex: 1, minHeight: 0, overflow: "hidden", width: "100%", justifyContent: "center" }}>
                                                <FiiDiiModule T={T} />
                                            </div>
                                        )}
                                        {financialSubPage === "ownership" && (
                                            <div style={{ display: "flex", flex: 1, minHeight: 0, overflow: "hidden", width: "100%" }}>
                                                <OwnershipScansModule T={T} />
                                            </div>
                                        )}
                                        {financialSubPage === "announcements" && (
                                            <div style={{ display: "flex", flex: 1, minHeight: 0, overflow: "hidden", width: "100%" }}>
                                                <AnnouncementsModule T={T} />
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* TECHNICALS */}
                                {productTab === "technical" && (
                                    <TechnicalAnalyticsModule T={T} subPage={technicalSubPage} onTechnoFundaScan={handleTechnoFundaScan} />
                                )}

                            </>
                        )}


                    </div>

                    {/*  PERSISTENT FOOTER  */}
                    <div className="persistent-footer" style={{
                        flexShrink: 0,
                        padding: "6px 20px",
                        background: T.surface,
                        borderTop: `1px solid ${T.border}`,
                        paddingBottom: `calc(6px + env(safe-area-inset-bottom, 0px))`,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        gap: 8,
                        flexWrap: "wrap",
                    }}>
                        {/* Left: copyright */}
                        <span style={{ fontSize: 11, color: T.subtext, opacity: .55, whiteSpace: "nowrap" }}>
                            {"\u00A9"} {new Date().getFullYear()} TradeEdge {"\u00B7"} Not SEBI registered
                        </span>
                        {/* Right: links */}
                        <div style={{ display: "flex", alignItems: "center", gap: 0, flexWrap: "wrap" }}>
                            {[
                                { label: "Disclaimer", tabId: "disclaimer", href: "/legal/disclaimer" },
                                { label: "Privacy", tabId: "privacy", href: "/legal/privacy" },
                                { label: "Terms", tabId: "terms", href: "/legal/terms" },
                                { label: "Contact Us", tabId: "contact", href: "/legal/contact" },
                            ].map((link, i) => (
                                <span key={link.label} style={{ display: "flex", alignItems: "center" }}>
                                    {i > 0 && <span style={{ fontSize: 11, color: T.border, margin: "0 5px", userSelect: "none" }}>{"\u00B7"}</span>}
                                    <a
                                        href={link.href}
                                        onClick={(event) => {
                                            event.preventDefault();
                                            openLegal(link.tabId);
                                        }}
                                        style={{ fontSize: 11, color: T.green, cursor: "pointer", padding: 0, fontFamily: "inherit", fontWeight: 500, opacity: .85, textDecoration: "none" }}
                                    >{link.label}</a>
                                </span>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {modal && <TradeModal trade={modal.mode === "edit" ? modal.trade : null} onClose={() => setModal(null)} onSave={handleSave} T={T} />}

            {/* Login Modal — shown when user clicks Login in the top nav */}
            {showLoginModal && (
                <LoginModal
                    onClose={() => setShowLoginModal(false)}
                    onLogin={(res) => { handleLogin(res); setShowLoginModal(false); }}
                    theme={theme}
                />
            )}
        </>
    );
}